INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:353f7688-f230-41ef-a181-8bd9341448cf:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Brown Willy Cairns', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s003-rollback:353f7688-f230-41ef-a181-8bd9341448cf:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Brown Willy Cairns', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "The Brown Willy summit cairn has never been excavated; the sources date only other Bodmin Moor cairns (2162-1746 cal BC) or say ''early Bronze Age'' without a year, so no two independent sources date this site''s start.", "value_page": null}]'::jsonb),
    ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=35404', 'https://en.wikipedia.org/wiki/Brown_Willy', 'fields-wd1-2026-09-26b-s003-rollback:353f7688-f230-41ef-a181-8bd9341448cf:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Brown_Willy'' restored on Brown Willy Cairns', '[{"source": "https://www.megalithic.co.uk/article.php?sid=35404", "url": "https://www.megalithic.co.uk/article.php?sid=35404", "quote": "Brown Willy is the highest natural hill in Cornwall. It has two cairns plus various settlement sites and a house platform.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Brown_Willy", "url": "https://en.wikipedia.org/wiki/Brown_Willy", "quote": "Brown Willy Summit Cairn has never been excavated and folklore suggests an ancient Cornish king may lie entombed underneath.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is the hill''s (''Brown Willy Cairns'' only redirects to a section of it); the Megalithic Portal''s Brown Willy Barrow Cemetery page is the readable page devoted to the two summit cairns, so it replaces the hill article.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'geom', 'SRID=4326;POINT(-3.58414 50.816679)', '0101000020E61000000EEB0C3D76640CC05310F0F991674940', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E61000000EEB0C3D76640CC05310F0F991674940'' restored on Raddon Top', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7765", "url": "https://www.megalithic.co.uk/article.php?sid=7765", "quote": "Latitude: 50.816679N Longitude: 3.58414W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/4947177756", "url": "https://www.openstreetmap.org/node/4947177756", "quote": "50.8170577, -3.5837118", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological site (Raddon Hill causewayed enclosure and hillfort) lies at SS 885 031, which the Megalithic Portal gives as 50.8167N 3.5841W and OpenStreetMap maps at 50.8171, -3.5837; the stored point is the Wikipedia/Wikidata point for the Raddon Top summit about 2.4 km further east, so the point is replaced.", "value_page": null}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'lat', '50.816679', '50.809142343729626', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:lat', 'rollback of fields-wd1-2026-09-26b-s003: lat ''50.809142343729626'' restored on Raddon Top', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7765", "url": "https://www.megalithic.co.uk/article.php?sid=7765", "quote": "Latitude: 50.816679N Longitude: 3.58414W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/4947177756", "url": "https://www.openstreetmap.org/node/4947177756", "quote": "50.8170577, -3.5837118", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological site (Raddon Hill causewayed enclosure and hillfort) lies at SS 885 031, which the Megalithic Portal gives as 50.8167N 3.5841W and OpenStreetMap maps at 50.8171, -3.5837; the stored point is the Wikipedia/Wikidata point for the Raddon Top summit about 2.4 km further east, so the point is replaced.", "value_page": null}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'lon', '-3.58414', '-3.549053647000057', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''-3.549053647000057'' restored on Raddon Top', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7765", "url": "https://www.megalithic.co.uk/article.php?sid=7765", "quote": "Latitude: 50.816679N Longitude: 3.58414W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/4947177756", "url": "https://www.openstreetmap.org/node/4947177756", "quote": "50.8170577, -3.5837118", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological site (Raddon Hill causewayed enclosure and hillfort) lies at SS 885 031, which the Megalithic Portal gives as 50.8167N 3.5841W and OpenStreetMap maps at 50.8171, -3.5837; the stored point is the Wikipedia/Wikidata point for the Raddon Top summit about 2.4 km further east, so the point is replaced.", "value_page": null}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Raddon Top', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Raddon Top', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "clear", "status": "MISSING", "reasoning": "The site begins with an early Neolithic causewayed enclosure, not in the stored 1500-500 BC bucket; only one readable page (a Megalithic Portal comment, ''C14 dates around 3500 calBC'') gives a year for it, and no second independent readable source dates the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=7765', 'https://en.wikipedia.org/wiki/Raddon_Top', 'fields-wd1-2026-09-26b-s003-rollback:35671923-e17a-4e2b-9333-bf31063c375b:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Raddon_Top'' restored on Raddon Top', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7765", "url": "https://www.megalithic.co.uk/article.php?sid=7765", "quote": "Excavations of a causewayed Enclosure and hillfort on Raddon Hill.", "outcome": "found"}, {"source": "https://visitmiddevon.co.uk/listing/raddon-hill/", "url": "https://visitmiddevon.co.uk/listing/raddon-hill/", "quote": "Raddon Hill is not only a beauty spot but also a site of great archaeological significance in Mid Devon.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the Raddon Top summit (short description ''Summit in England'', point 2.4 km from the monument); the Megalithic Portal page is the readable page about the Raddon Hill causewayed enclosure and hillfort itself, and Visit Mid Devon names the same archaeological site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('35809cfb-bde4-431a-8748-1aefdff5b0b0'::uuid, 'period_name', '1000 - 1500 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:35809cfb-bde4-431a-8748-1aefdff5b0b0:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Castle Hill, Torrington', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1139) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('35809cfb-bde4-431a-8748-1aefdff5b0b0'::uuid, 'period_start', '1139', '-1000', 'fields-wd1-2026-09-26b-s003-rollback:35809cfb-bde4-431a-8748-1aefdff5b0b0:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Castle Hill, Torrington', '[{"source": "https://great-torringtontowncouncil.gov.uk/2016/07/04/castle/", "url": "https://great-torringtontowncouncil.gov.uk/2016/07/04/castle/", "quote": "The original castle was built in the 12th century and the site is first mentioned in 1139 when it was attacked in the civil war", "outcome": "found"}, {"source": "http://castlefacts.info/castleDetails/castleDetails3?uin=10855", "url": "http://castlefacts.info/castleDetails/castleDetails3?uin=10855", "quote": "is recorded as having been captured and burnt in 1139", "outcome": "found"}, {"source": "https://www.digthecastle.com/archaeology-history/castle-timeline", "url": "https://www.digthecastle.com/archaeology-history/castle-timeline", "quote": "in October 1139, the castle at Great Torrington was burnt to the ground in a night raid", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "MISSING", "reasoning": "The Iron Age hillfort is only ''probably'' there and undated; the site''s securely attested history is the Norman castle, first recorded in 1139, which lies in the 1000 - 1500 AD bucket, not 1500 - 500 BC.", "value_page": null}]'::jsonb),
    ('35809cfb-bde4-431a-8748-1aefdff5b0b0'::uuid, 'site_type', 'Castle', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:35809cfb-bde4-431a-8748-1aefdff5b0b0:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Castle Hill, Torrington', '[{"source": "https://en.wikipedia.org/wiki/Castle_Hill,_Torrington", "url": "https://en.wikipedia.org/wiki/Castle_Hill,_Torrington", "quote": "is the site of the Norman and mediaeval castles", "outcome": "found"}, {"source": "http://castlefacts.info/castleDetails/castleDetails3?uin=10855", "url": "http://castlefacts.info/castleDetails/castleDetails3?uin=10855", "quote": "Has been described as a Certain Timber Castle (Motte), and also as a Certain Masonry Castle", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe Castle Hill as the site of the Norman motte-and-bailey and later masonry castle of Great Torrington; Castle is more specific than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('359860c8-9f39-49d7-8834-1651987c8c1e'::uuid, 'geom', 'SRID=4326;POINT(23.71861 37.97833)', '0101000020E61000003757F3E972BB37409EE5E062A3FE4240', 'fields-wd1-2026-09-26b-s003-rollback:359860c8-9f39-49d7-8834-1651987c8c1e:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E61000003757F3E972BB37409EE5E062A3FE4240'' restored on Funerary Naiskos of Aristonautes', '[{"source": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "url": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "quote": "37°58′41.988″N 23°43′6.996″E", "outcome": "found"}, {"source": "https://topostext.org/place/380237XKer", "url": "https://topostext.org/place/380237XKer", "quote": "Latitude: 37.978100 Longitude: 23.718800", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "replace", "status": "CONFLICT", "reasoning": "The naiskos (NAMA 738) stood in the Kerameikos cemetery near the Dipylon Gate (enwiki: ''stood near the Dipylon Gate in the Kerameikos''; Perseus: ''Found at Athens, Kerameikos (in 1864)''); the stored point is the National Archaeological Museum that now keeps it, 1.7 km away. The monument''s own Greek Wikipedia/Wikidata point and ToposText''s independent point for the Kerameikos both lie at the findspot, about 100 m apart, so the point moves there.", "value_page": null}]'::jsonb),
    ('359860c8-9f39-49d7-8834-1651987c8c1e'::uuid, 'lat', '37.97833', '37.98936115247055', 'fields-wd1-2026-09-26b-s003-rollback:359860c8-9f39-49d7-8834-1651987c8c1e:lat', 'rollback of fields-wd1-2026-09-26b-s003: lat ''37.98936115247055'' restored on Funerary Naiskos of Aristonautes', '[{"source": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "url": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "quote": "37°58′41.988″N 23°43′6.996″E", "outcome": "found"}, {"source": "https://topostext.org/place/380237XKer", "url": "https://topostext.org/place/380237XKer", "quote": "Latitude: 37.978100 Longitude: 23.718800", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "replace", "status": "CONFLICT", "reasoning": "The naiskos (NAMA 738) stood in the Kerameikos cemetery near the Dipylon Gate (enwiki: ''stood near the Dipylon Gate in the Kerameikos''; Perseus: ''Found at Athens, Kerameikos (in 1864)''); the stored point is the National Archaeological Museum that now keeps it, 1.7 km away. The monument''s own Greek Wikipedia/Wikidata point and ToposText''s independent point for the Kerameikos both lie at the findspot, about 100 m apart, so the point moves there.", "value_page": null}]'::jsonb),
    ('359860c8-9f39-49d7-8834-1651987c8c1e'::uuid, 'lon', '23.71861', '23.732222196492526', 'fields-wd1-2026-09-26b-s003-rollback:359860c8-9f39-49d7-8834-1651987c8c1e:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''23.732222196492526'' restored on Funerary Naiskos of Aristonautes', '[{"source": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "url": "https://el.wikipedia.org/wiki/%CE%95%CF%80%CE%B9%CF%84%CF%8D%CE%BC%CE%B2%CE%B9%CE%B1_%CF%83%CF%84%CE%AE%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%91%CF%81%CE%B9%CF%83%CF%84%CE%BF%CE%BD%CE%B1%CF%8D%CF%84%CE%B7", "quote": "37°58′41.988″N 23°43′6.996″E", "outcome": "found"}, {"source": "https://topostext.org/place/380237XKer", "url": "https://topostext.org/place/380237XKer", "quote": "Latitude: 37.978100 Longitude: 23.718800", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "replace", "status": "CONFLICT", "reasoning": "The naiskos (NAMA 738) stood in the Kerameikos cemetery near the Dipylon Gate (enwiki: ''stood near the Dipylon Gate in the Kerameikos''; Perseus: ''Found at Athens, Kerameikos (in 1864)''); the stored point is the National Archaeological Museum that now keeps it, 1.7 km away. The monument''s own Greek Wikipedia/Wikidata point and ToposText''s independent point for the Kerameikos both lie at the findspot, about 100 m apart, so the point moves there.", "value_page": null}]'::jsonb),
    ('364ea265-5078-4181-a4de-46b51309996e'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:364ea265-5078-4181-a4de-46b51309996e:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Monte Bubbonia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('364ea265-5078-4181-a4de-46b51309996e'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:364ea265-5078-4181-a4de-46b51309996e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Monte Bubbonia', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "clear", "status": "MISSING", "reasoning": "The Sicilia in Rete heritage record, the Beni culturali di Gela page and Salvatore Piccolo on the Megalithic Portal all attest an Early Bronze Age (Castelluccio) settlement on Monte Bubbonia, earlier than the 7th-6th century BC tombs and the 6th-century town that are the only dated phases; no source dates that Bronze Age start in years, centuries or millennia for this site, so the stored -1500 cannot be confirmed and neither can a replacement - the field is emptied.", "value_page": null}]'::jsonb),
    ('3651b680-869e-4ee1-835a-1c0c2305eb5b'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:3651b680-869e-4ee1-835a-1c0c2305eb5b:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on Uxellodunum', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3651b680-869e-4ee1-835a-1c0c2305eb5b'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s003-rollback:3651b680-869e-4ee1-835a-1c0c2305eb5b:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on Uxellodunum', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "clear", "status": "MISSING", "reasoning": "The only dated event that the sources agree on is Caesar''s siege of 51 BC, and that is not the start. French Wikipedia and the excavators'' association (uxellodunum.com) describe important occupation of the plateau from the Late Bronze Age (''Bronze final''), which lies before the stored 500 BC - 1 AD bucket, but they give it no year or century. Only one source family dates the Gallic walled habitat (La Tène III, 2nd-1st century BC), so no two independent sources date the start, and the field is cleared.", "value_page": null}]'::jsonb),
    ('3651b680-869e-4ee1-835a-1c0c2305eb5b'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:3651b680-869e-4ee1-835a-1c0c2305eb5b:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Uxellodunum', '[{"source": "https://en.wikipedia.org/wiki/Uxellodunum", "url": "https://en.wikipedia.org/wiki/Uxellodunum", "quote": "Uxellodunum is an Iron Age hill fort", "outcome": "found"}, {"source": "https://archeologie.culture.gouv.fr/sources-archeologie/en/glossary/uxellodunum", "url": "https://archeologie.culture.gouv.fr/sources-archeologie/en/glossary/uxellodunum", "quote": "Uxellodunum was the last Gallic stronghold placed under siege by Julius Caesar in 51 BCE. The oppidum of Uxellodunum belonged to the Cadurques", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Uxellodunum an Iron Age hill fort (oppidum), and the French Ministry of Culture calls it a Gallic stronghold and oppidum at Le Puy-d''Issolud, Vayrac. The most specific canonical type for a fortified Iron Age hill site is Fort, not Fortress/citadel.", "value_page": null}]'::jsonb),
    ('36778e23-1b9f-4094-a1cb-d3e1272e8d35'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:36778e23-1b9f-4094-a1cb-d3e1272e8d35:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Isla de Sacrificios', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('36778e23-1b9f-4094-a1cb-d3e1272e8d35'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:36778e23-1b9f-4094-a1cb-d3e1272e8d35:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Isla de Sacrificios', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "clear", "status": "MISSING", "reasoning": "Sources only name periods for the island''s use (Totonac ceremonies in the Postclassic per Spanish Wikipedia; the 1950-51 excavation report is said to record earlier Remojadas material); no two independent readable sources state a year or century for the start of the site, so the stored 1 AD is unsupported.", "value_page": null}]'::jsonb),
    ('36778e23-1b9f-4094-a1cb-d3e1272e8d35'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=31058', 'https://en.wikipedia.org/wiki/Isla_de_Sacrificios', 'fields-wd1-2026-09-26b-s003-rollback:36778e23-1b9f-4094-a1cb-d3e1272e8d35:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Isla_de_Sacrificios'' restored on Isla de Sacrificios', '[{"source": "https://www.megalithic.co.uk/article.php?sid=31058", "url": "https://www.megalithic.co.uk/article.php?sid=31058", "quote": "Site Name: Isla de Sacrificios Country: Mexico Region: Veracruz Type: Ancient Temple", "outcome": "found"}, {"source": "https://diccionariover.uv.mx/egvadmin/bin/view/enciclopedia/Sacrificios%2C%20isla%20de", "url": "https://diccionariover.uv.mx/egvadmin/bin/view/enciclopedia/Sacrificios%2C%20isla%20de", "quote": "Isla de Sacrificios (isla-zona arqueológica-Veracruz)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is the island''s (infobox ''Island in Mexico''); no Wikipedia article covers the archaeological site itself, while the Megalithic Portal entry is about the ancient temple site of Isla de Sacrificios, which the Universidad Veracruzana''s encyclopedia also records as an archaeological zone.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
