    ('3696838c-9f7e-4e20-aaf8-841af9e7690d'::uuid, 'site_type', 'Villa', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s003-rollback:3696838c-9f7e-4e20-aaf8-841af9e7690d:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Residence/villa/farmhouse'' restored on Brighstone', '[{"source": "https://www.aubreyresearch.com/uk/roman-britain/sites/rock-roman-villa", "url": "https://www.aubreyresearch.com/uk/roman-britain/sites/rock-roman-villa", "quote": "Rock Roman villa is a Roman villa site recorded in the Pleiades ancient world gazetteer.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Brighstone", "url": "https://en.wikipedia.org/wiki/Brighstone", "quote": "In Roman times a villa was built to the north, to take advantage of the clean waters of the", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as a Roman villa (a small corridor house); Villa is the more specific canonical type than Residence/villa/farmhouse.", "value_page": null}]'::jsonb),
    ('3696838c-9f7e-4e20-aaf8-841af9e7690d'::uuid, 'source_url', 'https://www.wikidata.org/wiki/Q17648120', 'https://en.wikipedia.org/wiki/Brighstone', 'fields-wd1-2026-09-26b-s003-rollback:3696838c-9f7e-4e20-aaf8-841af9e7690d:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Brighstone'' restored on Brighstone', '[{"source": "https://www.wikidata.org/wiki/Q17648120", "url": "https://www.wikidata.org/wiki/Q17648120", "quote": "Rock Roman villa archaeological site in Brighstone, Isle of Wight, England, UK", "outcome": "found"}, {"source": "https://theillustratedlifeandtimes.wordpress.com/2026/08/07/robert-cooper-finds-a-roman-villa/", "url": "https://theillustratedlifeandtimes.wordpress.com/2026/08/07/robert-cooper-finds-a-roman-villa/", "quote": "Image: This is not the Roman villa at Rock, but it gives us an idea of what early excavations under Brighstone Down might have looked like.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the village. The villa has no Wikipedia article and its Historic England list entry cannot be read by the checker; the Wikidata item for Rock Roman villa is about the site itself (scheduled monument 1008304 with its coordinates).", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3696e872-ce24-42c2-b632-fe7b034171df'::uuid, 'site_type', 'Settlement', 'Megalithic stones', 'fields-wd1-2026-09-26b-s003-rollback:3696e872-ce24-42c2-b632-fe7b034171df:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic stones'' restored on Karahan Tepe', '[{"source": "https://www.anatolianarchaeology.net/karahantepe-offers-clues-that-gobeklitepe-was-more-than-a-ritual-site/", "url": "https://www.anatolianarchaeology.net/karahantepe-offers-clues-that-gobeklitepe-was-more-than-a-ritual-site/", "quote": "the remaining area points to one of the largest known Neolithic settlements in Anatolia", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Karahan_Tepe", "url": "https://en.wikipedia.org/wiki/Karahan_Tepe", "quote": "Additionally, the site may be the earliest known human village, predating the construction of Göbekli Tepe by several centuries, dating to between 10,000 and 9500 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavators describe Karahantepe as one of the largest Neolithic settlements in Anatolia, with domestic huts around communal buildings, and Wikipedia calls it possibly the earliest known human village; the site is a Neolithic settlement mound (Wikidata: tell), so Settlement fits better than Megalithic stones.", "value_page": null}]'::jsonb),
    ('37065cce-99dd-4055-bd92-4906840149e6'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s003-rollback:37065cce-99dd-4055-bd92-4906840149e6:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''< 4500 BC'' restored on Carn Kenidjack', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('37065cce-99dd-4055-bd92-4906840149e6'::uuid, 'period_start', NULL, '-5000', 'fields-wd1-2026-09-26b-s003-rollback:37065cce-99dd-4055-bd92-4906840149e6:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-5000'' restored on Carn Kenidjack', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "clear", "status": "MISSING", "reasoning": "The sources describe Carn Kenidjack as a natural outcrop; a possible Neolithic tor enclosure on it is mentioned only in comments and is not securely dated, so no two sources date a start and the stored -5000 cannot be sourced.", "value_page": null}]'::jsonb),
    ('37065cce-99dd-4055-bd92-4906840149e6'::uuid, 'site_type', 'Natural feature', 'Megalithic stones', 'fields-wd1-2026-09-26b-s003-rollback:37065cce-99dd-4055-bd92-4906840149e6:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic stones'' restored on Carn Kenidjack', '[{"source": "https://www.megalithic.co.uk/article.php?sid=35497", "url": "https://www.megalithic.co.uk/article.php?sid=35497", "quote": "Carn Kenidjack (Hooting Cairn) is a big natural outcrop supposedly named because of the noise the wind makes around the rocks", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Carn_Kenidjack", "url": "https://en.wikipedia.org/wiki/Carn_Kenidjack", "quote": "is a hill in Tregeseal, Cornwall, UK. It is covered in megaliths including Tregeseal East stone circle.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal classes Carn Kenidjack as a natural rock outcrop and Wikipedia as a hill; the megaliths (Tregeseal stone circle, holed stones) are separate monuments around it, so Natural feature fits better than Megalithic stones.", "value_page": null}]'::jsonb),
    ('37321e41-a629-4d79-820d-3104c7713860'::uuid, 'site_type', 'City/town/settlement', 'Megalithic stones', 'fields-wd1-2026-09-26b-s003-rollback:37321e41-a629-4d79-820d-3104c7713860:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic stones'' restored on Site de Tiklat', '[{"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=tubusuctu", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=tubusuctu", "quote": "The town lies in a valley on the left bank of the Soummam, occupying an eminence and the plain running along it on S and E, where there are still vestiges of ramparts.", "outcome": "found"}, {"source": "https://www.saravoyages.com/decouvrirtubusuptu.html", "url": "https://www.saravoyages.com/decouvrirtubusuptu.html", "quote": "la ville antique de Tubusuctu (Tiklat)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "The Princeton Encyclopedia of Classical Sites describes Tubusuctu at Tiklat as a Roman colony town with ramparts, baths and cisterns, and a regional tourism page calls it the ancient town of Tubusuctu; no source mentions megaliths, so ''Megalithic stones'' is wrong and the Roman town is City/town/settlement.", "value_page": null}]'::jsonb),
    ('37321e41-a629-4d79-820d-3104c7713860'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tubusuctu', 'https://fr.wikipedia.org/wiki/Tubusuptu', 'fields-wd1-2026-09-26b-s003-rollback:37321e41-a629-4d79-820d-3104c7713860:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://fr.wikipedia.org/wiki/Tubusuptu'' restored on Site de Tiklat', '[{"source": "https://en.wikipedia.org/wiki/Tubusuctu", "url": "https://en.wikipedia.org/wiki/Tubusuctu", "quote": "The region''s olive oil was very popular and Tiklat jars were found throughout the Roman Empire", "outcome": "found"}, {"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=tubusuctu", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0006:entry=tubusuctu", "quote": "TUBUSUCTU or Tubusuptu (Tiklat) Algeria. Situated 3 km from El Kseur and 30 km S of Bougie, on the Soummam River.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "The stored French article Tubusuptu is about the site but is a stub; the English article Tubusuctu is the site''s own article (the Roman colony at Tiklat near El Kseur), preferred as English, and the Princeton Encyclopedia names the same colony.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Tubusuctu", "unreadable": false, "wikibase_item": "Q3541821"}}]'::jsonb),
    ('3746f91f-e0e5-4494-9ea6-0261ba241fe1'::uuid, 'site_type', 'Temple', 'Megalithic structures', 'fields-wd1-2026-09-26b-s003-rollback:3746f91f-e0e5-4494-9ea6-0261ba241fe1:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic structures'' restored on Debdieba', '[{"source": "https://en.wikipedia.org/wiki/Debdieba", "url": "https://en.wikipedia.org/wiki/Debdieba", "quote": "Debdieba (Maltese: Id-Debdieba) is a megalithic temple in Luqa, Malta", "outcome": "found"}, {"source": "http://archive.maltatoday.com.mt/2007/07/08/n1.html", "url": "http://archive.maltatoday.com.mt/2007/07/08/n1.html", "quote": "to ensure that a unique temple, known as id-Debdieba, which lies buried under the runway, is not tampered with.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0093)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources call Debdieba a (megalithic, Neolithic) temple, one of the Maltese temple sites; Temple is more specific than the stored ''Megalithic structures''.", "value_page": null}]'::jsonb),
    ('37808e2a-8837-485c-9b69-f103a2be79b4'::uuid, 'site_type', 'Forum', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:37808e2a-8837-485c-9b69-f103a2be79b4:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Macellum of Naples', '[{"source": "https://tour.napoli.it/it/napoli/cosa-vedere/dettagli/area-archeologica-del-complesso-di-san-lorenzo-maggiore", "url": "https://tour.napoli.it/it/napoli/cosa-vedere/dettagli/area-archeologica-del-complesso-di-san-lorenzo-maggiore", "quote": "area archeologica, in cui sono visibili i resti dell’antico Foro di Neapolis", "outcome": "found"}, {"source": "https://www.veranapoli.com/musei/neapolis-napoli.html", "url": "https://www.veranapoli.com/musei/neapolis-napoli.html", "quote": "Questa Agorà divenne poi il Forum Vetus in epoca romana, un foro romano", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Macellum_of_Naples", "url": "https://en.wikipedia.org/wiki/Macellum_of_Naples", "quote": "The Macellum of Naples was the macellum or market building of the Roman city of Neapolis", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0085)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is not a settlement but the macellum (market building) of Roman Neapolis, set in the agora/forum area beneath San Lorenzo Maggiore; the City of Naples calls the area the remains of the ancient Forum of Neapolis, so Forum is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('37c35150-d91b-44bb-a039-48783357de8e'::uuid, 'geom', 'SRID=4326;POINT(20.499206 44.513415)', '0101000020E6100000326868C4CB903440767E41D89C3B4640', 'fields-wd1-2026-09-26b-s003-rollback:37c35150-d91b-44bb-a039-48783357de8e:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E6100000326868C4CB903440767E41D89C3B4640'' restored on Kosmaj', '[{"source": "https://imperium.ahlfeldt.se/places/26417.html", "url": "https://imperium.ahlfeldt.se/places/26417.html", "quote": "WGS 84 position 44.507562, 20.499254", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q103167149", "url": "https://www.wikidata.org/wiki/Q103167149", "quote": "44°31''9.361\"N, 20°29''56.969\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Roman silver and lead mines of Kosmaj, whose central zone lies between Guberevac, Stojnik, Babe and Parcani with the castellum at Gradiste near Stojnik at its heart (Maric & Crnobrnja, Nis i Vizantija XXIII). The Digital Atlas of the Roman Empire (Barrington ''Stojnik'', mine Ag, mine Pb) and Samian Research''s ''Kosmaj-Stojnik'' site put that centre at 44.508-44.519, 20.499; the value lies between them, within 0.7 km of each. The stored point is the Kosmaj summit, about 7.5 km to the south-east. OXREP''s minute-rounded 44.466667, 20.566667 is that same summit, not the mines.", "value_page": null}]'::jsonb),
    ('37c35150-d91b-44bb-a039-48783357de8e'::uuid, 'lat', '44.513415', '44.46572402189206', 'fields-wd1-2026-09-26b-s003-rollback:37c35150-d91b-44bb-a039-48783357de8e:lat', 'rollback of fields-wd1-2026-09-26b-s003: lat ''44.46572402189206'' restored on Kosmaj', '[{"source": "https://imperium.ahlfeldt.se/places/26417.html", "url": "https://imperium.ahlfeldt.se/places/26417.html", "quote": "WGS 84 position 44.507562, 20.499254", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q103167149", "url": "https://www.wikidata.org/wiki/Q103167149", "quote": "44°31''9.361\"N, 20°29''56.969\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Roman silver and lead mines of Kosmaj, whose central zone lies between Guberevac, Stojnik, Babe and Parcani with the castellum at Gradiste near Stojnik at its heart (Maric & Crnobrnja, Nis i Vizantija XXIII). The Digital Atlas of the Roman Empire (Barrington ''Stojnik'', mine Ag, mine Pb) and Samian Research''s ''Kosmaj-Stojnik'' site put that centre at 44.508-44.519, 20.499; the value lies between them, within 0.7 km of each. The stored point is the Kosmaj summit, about 7.5 km to the south-east. OXREP''s minute-rounded 44.466667, 20.566667 is that same summit, not the mines.", "value_page": null}]'::jsonb),
    ('37c35150-d91b-44bb-a039-48783357de8e'::uuid, 'lon', '20.499206', '20.565609240999216', 'fields-wd1-2026-09-26b-s003-rollback:37c35150-d91b-44bb-a039-48783357de8e:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''20.565609240999216'' restored on Kosmaj', '[{"source": "https://imperium.ahlfeldt.se/places/26417.html", "url": "https://imperium.ahlfeldt.se/places/26417.html", "quote": "WGS 84 position 44.507562, 20.499254", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q103167149", "url": "https://www.wikidata.org/wiki/Q103167149", "quote": "44°31''9.361\"N, 20°29''56.969\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Roman silver and lead mines of Kosmaj, whose central zone lies between Guberevac, Stojnik, Babe and Parcani with the castellum at Gradiste near Stojnik at its heart (Maric & Crnobrnja, Nis i Vizantija XXIII). The Digital Atlas of the Roman Empire (Barrington ''Stojnik'', mine Ag, mine Pb) and Samian Research''s ''Kosmaj-Stojnik'' site put that centre at 44.508-44.519, 20.499; the value lies between them, within 0.7 km of each. The stored point is the Kosmaj summit, about 7.5 km to the south-east. OXREP''s minute-rounded 44.466667, 20.566667 is that same summit, not the mines.", "value_page": null}]'::jsonb),
    ('37c35150-d91b-44bb-a039-48783357de8e'::uuid, 'site_type', 'Mine', 'Mine/quarry', 'fields-wd1-2026-09-26b-s003-rollback:37c35150-d91b-44bb-a039-48783357de8e:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Mine/quarry'' restored on Kosmaj', '[{"source": "https://oxrep.classics.ox.ac.uk/popup.php?ste=2101", "url": "https://oxrep.classics.ox.ac.uk/popup.php?ste=2101", "quote": "Kosmaj Mine Coordinates: 44.466667°N 20.566667°E Serbia / Moesia Superior", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kosmaj", "url": "https://en.wikipedia.org/wiki/Kosmaj", "quote": "In the 3rd century AD, the Kosmaj mines were one of the most important in the Roman Empire", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Oxford Roman Economy Project lists the site as the Kosmaj Mine (lead and silver, underground mining with galleries, pits and slag heaps), and Wikipedia describes the Kosmaj mines as among the most important in the Roman Empire. No quarry is reported, so the more specific canonical type Mine replaces Mine/quarry.", "value_page": null}]'::jsonb),
    ('37c35150-d91b-44bb-a039-48783357de8e'::uuid, 'source_url', 'https://oxrep.classics.ox.ac.uk/popup.php?ste=2101', 'https://en.wikipedia.org/wiki/Kosmaj', 'fields-wd1-2026-09-26b-s003-rollback:37c35150-d91b-44bb-a039-48783357de8e:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Kosmaj'' restored on Kosmaj', '[{"source": "https://oxrep.classics.ox.ac.uk/popup.php?ste=2101", "url": "https://oxrep.classics.ox.ac.uk/popup.php?ste=2101", "quote": "Kosmaj Mine Coordinates: 44.466667°N 20.566667°E Serbia / Moesia Superior", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kosmaj", "url": "https://en.wikipedia.org/wiki/Kosmaj", "quote": "In the 3rd century AD, the Kosmaj mines were one of the most important in the Roman Empire", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about Kosmaj mountain, and no Wikipedia in any language has an article on the Roman mines. The Oxford Roman Economy Project mines database has an entry for this very site, the Kosmaj Mine (lead and silver, underground mining), and it loads as plain HTML. Wikipedia independently names the Kosmaj mines.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('37d8c068-dfb3-4fc5-a99e-a09c4aad18d3'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:37d8c068-dfb3-4fc5-a99e-a09c4aad18d3:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Susupillo', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('37d8c068-dfb3-4fc5-a99e-a09c4aad18d3'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:37d8c068-dfb3-4fc5-a99e-a09c4aad18d3:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Susupillo', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0114)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates Susupillo itself: the tourism inventory places it in the Late Intermediate Period without a year, while press and travel pages give only a hedged 10th-14th century range for the whole Tantamayo complex; the stored 1 AD (the mountain item''s bucket) is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('37d8c068-dfb3-4fc5-a99e-a09c4aad18d3'::uuid, 'site_type', 'Castle/palace', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:37d8c068-dfb3-4fc5-a99e-a09c4aad18d3:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Susupillo', '[{"source": "https://www.infobae.com/peru/2024/02/17/los-rascacielos-de-tantamayo-edificios-de-hasta-cinco-pisos-y-16-de-habitaciones-que-fueron-construidos-por-una-cultura-preinca-en-huanuco/", "url": "https://www.infobae.com/peru/2024/02/17/los-rascacielos-de-tantamayo-edificios-de-hasta-cinco-pisos-y-16-de-habitaciones-que-fueron-construidos-por-una-cultura-preinca-en-huanuco/", "quote": "Uno de los edificios que llama la atención es conocido como el Castillo de Susupillo, catalogado como el edificio prehistórico más alto de América, ya que tiene nada menos que cinco pisos, 16 habitaciones, 2 pabellones y hasta un altar.", "outcome": "found"}, {"source": "https://www.turismoperuano.com/complejo-arqueologico-susupillo-huanuco", "url": "https://www.turismoperuano.com/complejo-arqueologico-susupillo-huanuco", "quote": "considerado los rascacielos de América y la sede de la elite política, centro de mando del primer personaje de la colectividad, príncipe por herencia o jefe por elección", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0020)", "decision": "replace", "status": "CONFLICT", "reasoning": "Susupillo (Tantamayo, Huamalies, Huanuco) is not a town: the sources describe one five-storey stone building of the Tantamayo (Yarowilca) culture with 16 rooms, pavilions and an altar, known as the Castillo de Susupillo (Infobae) and described by the tourism inventory as the seat of the political elite and command centre of the community''s leader, protected by semicircular walls. That is a castle/palace, not the stored City/town/settlement; the Wikidata mountain item is only the hill the building stands on.", "value_page": null}]'::jsonb),
    ('37d8c068-dfb3-4fc5-a99e-a09c4aad18d3'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=46153', 'https://en.wikipedia.org/wiki/Susupillo', 'fields-wd1-2026-09-26b-s003-rollback:37d8c068-dfb3-4fc5-a99e-a09c4aad18d3:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Susupillo'' restored on Susupillo', '[{"source": "https://www.megalithic.co.uk/article.php?sid=46153", "url": "https://www.megalithic.co.uk/article.php?sid=46153", "quote": "Site Name: Susupillo Country: Peru Type: Hillfort Nearest Village: Tantamayo", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Susupillo", "url": "https://en.wikipedia.org/wiki/Susupillo", "quote": "The archaeological site of Susupillo lies on the northern slope of the mountain", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0114)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is primarily the mountain''s (mountain infobox and point); the Megalithic Portal entry is a page about the Susupillo ruins themselves, which Wikipedia confirms as the archaeological site of the same name near Tantamayo.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3842aca5-13d3-4166-80cf-92f8dac3514f'::uuid, 'geom', 'SRID=4326;POINT(-71.734088 -13.607518)', '0101000020E6100000A2ABFD4667EF51C0D0718CFADD462BC0', 'fields-wd1-2026-09-26b-s003-rollback:3842aca5-13d3-4166-80cf-92f8dac3514f:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E6100000A2ABFD4667EF51C0D0718CFADD462BC0'' restored on Choquepuquio', '[{"source": "https://www.megalithic.co.uk/article.php?sid=27228", "url": "https://www.megalithic.co.uk/article.php?sid=27228", "quote": "Latitude: 13.607518S Longitude: 71.734088W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/1728415656", "url": "https://www.openstreetmap.org/node/1728415656", "quote": "-13.6073114, -71.7338890", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal entry for Chokepukio and the OpenStreetMap archaeological-site node (Choccepujo/Choquepuquio, Huacarpay) place the ruins within 30 m of each other beside the highway at Huacarpay, about 1.9 km WNW of Pikillaqta; the stored point is the coordinate of the town of Lucre (district seat), about 3.5 km south, and the Wikidata point lies about 1.8 km off near Pikillaqta.", "value_page": null}]'::jsonb),
