    ('3842aca5-13d3-4166-80cf-92f8dac3514f'::uuid, 'lon', '-71.734088', '-71.7406785466433', 'fields-wd1-2026-09-26b-s003-rollback:3842aca5-13d3-4166-80cf-92f8dac3514f:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''-71.7406785466433'' restored on Choquepuquio', '[{"source": "https://www.megalithic.co.uk/article.php?sid=27228", "url": "https://www.megalithic.co.uk/article.php?sid=27228", "quote": "Latitude: 13.607518S Longitude: 71.734088W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/1728415656", "url": "https://www.openstreetmap.org/node/1728415656", "quote": "-13.6073114, -71.7338890", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal entry for Chokepukio and the OpenStreetMap archaeological-site node (Choccepujo/Choquepuquio, Huacarpay) place the ruins within 30 m of each other beside the highway at Huacarpay, about 1.9 km WNW of Pikillaqta; the stored point is the coordinate of the town of Lucre (district seat), about 3.5 km south, and the Wikidata point lies about 1.8 km off near Pikillaqta.", "value_page": null}]'::jsonb),
    ('3842aca5-13d3-4166-80cf-92f8dac3514f'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:3842aca5-13d3-4166-80cf-92f8dac3514f:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Choquepuquio', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-200) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3842aca5-13d3-4166-80cf-92f8dac3514f'::uuid, 'period_start', '-200', '1', 'fields-wd1-2026-09-26b-s003-rollback:3842aca5-13d3-4166-80cf-92f8dac3514f:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Choquepuquio', '[{"source": "https://southernct.elsevierpure.com/en/publications/strontium-isotope-evidence-for-prehistoric-migration-at-chokepuki-2/", "url": "https://southernct.elsevierpure.com/en/publications/strontium-isotope-evidence-for-prehistoric-migration-at-chokepuki-2/", "quote": "the isotope results do not provide evidence for migration at this site from the time periods preceding the rise of the Inca Empire (200 B.C. to A.D. 1400)", "outcome": "found"}, {"source": "https://thecolcaspecialist.blogspot.com/2012/09/investigating-child-sacrifice-event.html", "url": "https://thecolcaspecialist.blogspot.com/2012/09/investigating-child-sacrifice-event.html", "quote": "a stratified site in the Cuzco Valley occupied continuously from the Early Intermediate Period (~400 BC–AD 540) through the Late Horizon (AD 1476–1532)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "Andrushko et al. (Latin American Antiquity 2009) date the site''s occupation from 200 B.C., and their 2011 Journal of Archaeological Science paper (reproduced on the blog) has Choquepukio occupied continuously from the Early Intermediate Period (~400 BC-AD 540); both put the first occupation in 500 BC - 1 AD, not in the stored 1 - 500 AD bucket (the Wikipedia ''c. 400 CE'' is unsourced).", "value_page": null}]'::jsonb),
    ('3853519f-9215-4935-8f41-faae64286c3e'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3853519f-9215-4935-8f41-faae64286c3e:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Creech Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3853519f-9215-4935-8f41-faae64286c3e'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s003-rollback:3853519f-9215-4935-8f41-faae64286c3e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Creech Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "clear", "status": "MISSING", "reasoning": "The Somerset HER text (as reproduced by Digital Digging) calls the site an ''Early Iron age earthwork'' and gives no year or century. The aubreyresearch summary says its precise dating within the Iron Age is unresolved, and Wikipedia gives only a generic statement about hillforts in general. No two sources date the start with a year, century or millennium.", "value_page": null}]'::jsonb),
    ('38aefc7c-1eb9-42d2-bd76-8d6b70847e35'::uuid, 'period_name', '1 - 500 AD', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s003-rollback:38aefc7c-1eb9-42d2-bd76-8d6b70847e35:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 - 1000 AD'' restored on Kuélap', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(401) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('38aefc7c-1eb9-42d2-bd76-8d6b70847e35'::uuid, 'period_start', '401', '500', 'fields-wd1-2026-09-26b-s003-rollback:38aefc7c-1eb9-42d2-bd76-8d6b70847e35:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''500'' restored on Kuélap', '[{"source": "https://en.wikipedia.org/wiki/Ku%C3%A9lap", "url": "https://en.wikipedia.org/wiki/Ku%C3%A9lap", "quote": "Human occupation at the site starts in the 5th century AD,", "outcome": "found"}, {"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=754", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=754", "quote": "cuya ocupación comienza aproximadamente en el siglo V de nuestra era y culmina con la presencia española temprana en el siglo XVI", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0111)", "decision": "replace", "status": "MISSING", "reasoning": "Peru''s official MINCETUR inventory says occupation of the citadel begins about the 5th century AD, and Wikipedia''s history section and infobox put the first human occupation in the 5th century AD (the bulk of the building 900-1100); the start therefore lies in the 1 - 500 AD bucket, not in 500 - 1000 AD.", "value_page": null}]'::jsonb),
    ('39461539-85ee-47d9-9f64-b6a6587844ec'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:39461539-85ee-47d9-9f64-b6a6587844ec:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Spartia Temple', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('39461539-85ee-47d9-9f64-b6a6587844ec'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:39461539-85ee-47d9-9f64-b6a6587844ec:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Spartia Temple', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources (Wikipedia, Kathimerini/eKathimerini, ToposText) date the Herakles sanctuary only to the ''archaic period'' or ''archaic era'' without a year or century; the papers that give the sixth century BC (Taylor & Francis STAR 2018, academia.edu) refuse automated requests, so no two independent sources can be quoted for a dated start.", "value_page": null}]'::jsonb),
    ('398c3ef8-56c3-4640-a28a-ebaa8a36df33'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:398c3ef8-56c3-4640-a28a-ebaa8a36df33:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Ebsbury', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('398c3ef8-56c3-4640-a28a-ebaa8a36df33'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:398c3ef8-56c3-4640-a28a-ebaa8a36df33:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Ebsbury', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia (from the Historic England research record) calls the site''s earliest structures an Iron Age enclosed settlement and possible hill fort, and the Megalithic Portal files it under ''Iron Age and Later Prehistory''. Neither gives a year or century for the start. The only dated finds are Roman coins of AD 337-408, which mark late use rather than the start, so no two sources date the start and the stored 1 - 500 AD bucket is not supported.", "value_page": null}]'::jsonb),
    ('398c3ef8-56c3-4640-a28a-ebaa8a36df33'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:398c3ef8-56c3-4640-a28a-ebaa8a36df33:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Ebsbury', '[{"source": "https://en.wikipedia.org/wiki/Ebsbury", "url": "https://en.wikipedia.org/wiki/Ebsbury", "quote": "enclosed settlement, field system and possible hill fort", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8061", "url": "https://www.megalithic.co.uk/article.php?sid=8061", "quote": "Hillfort in Wiltshire", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0006)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia describes Ebsbury (Wiltshire, spur of Ebsbury Hill above the Wylye valley) as an Iron Age enclosed settlement, field system and possible hill fort, and the Megalithic Portal lists the site ''Ebsbury'' (Great Wishford, Wiltshire) as a hillfort; both name a hill fort, not a city or town, so the type is Fort.", "value_page": null}]'::jsonb),
    ('39927155-7597-4da8-9e3f-8c02d3d7a6ac'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s003-rollback:39927155-7597-4da8-9e3f-8c02d3d7a6ac:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''< 4500 BC'' restored on Jinkiori', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('39927155-7597-4da8-9e3f-8c02d3d7a6ac'::uuid, 'period_start', NULL, '-5000', 'fields-wd1-2026-09-26b-s003-rollback:39927155-7597-4da8-9e3f-8c02d3d7a6ac:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-5000'' restored on Jinkiori', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "Hostnig''s study of the Hinkiori petroglyphs, the Wikipedia articles and the MINCETUR inventory text attribute the engravings to Amazonian peoples, possibly ancestors of the Huachipaeri, but give no date. The stored value of 5000 BC has no support, so the field is cleared.", "value_page": null}]'::jsonb),
    ('3a1d65e1-389c-4ceb-9eb1-50af9efeec1e'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3a1d65e1-389c-4ceb-9eb1-50af9efeec1e:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Bolt Tail', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3a1d65e1-389c-4ceb-9eb1-50af9efeec1e'::uuid, 'period_start', '-300', '-1000', 'fields-wd1-2026-09-26b-s003-rollback:3a1d65e1-389c-4ceb-9eb1-50af9efeec1e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Bolt Tail', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "quote": "The visible inturned entrance is of a type dated elsewhere in theregion between about 300 BC and the Roman Conquest, so it is probable that Bolt Tail was built in the Later Iron Age.", "outcome": "found"}, {"source": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "url": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "quote": "similar to other promontory forts in the South West dating to about 300BC; so it is likely this promontory hill fort dates to the late Iron Age.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "MISSING", "reasoning": "The National Trust''s heritage record and Devon County Council''s historic environment page both date the unexcavated fort by its inturned entrance to about 300 BC or later (Later Iron Age); that start lies in the 500 BC - 1 AD bucket, not the stored 1500 - 500 BC one, so it is replaced with -300.", "value_page": null}]'::jsonb),
    ('3a1d65e1-389c-4ceb-9eb1-50af9efeec1e'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:3a1d65e1-389c-4ceb-9eb1-50af9efeec1e:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Bolt Tail', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "quote": "Bolt Tail headland is occupied by an Iron Age promontory fort of approximately 4.9 hectares", "outcome": "found"}, {"source": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "url": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "quote": "is the Iron Age promontory fort of Bolt Tail.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both heritage bodies describe the site as an Iron Age promontory fort on the headland (the Wikidata item is only the headland); Fort is the most specific canonical type, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('3a1d65e1-389c-4ceb-9eb1-50af9efeec1e'::uuid, 'source_url', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185', 'https://en.wikipedia.org/wiki/Bolt_Tail', 'fields-wd1-2026-09-26b-s003-rollback:3a1d65e1-389c-4ceb-9eb1-50af9efeec1e:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Bolt_Tail'' restored on Bolt Tail', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108185", "quote": "Bolt Tail Camp, Promontry Fort, Marlborough, South Hams", "outcome": "found"}, {"source": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "url": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/bolt-tail/", "quote": "is the Iron Age promontory fort of Bolt Tail.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is a stub about the headland; the National Trust Heritage Records entry ''Bolt Tail Camp, Promontry Fort'' (scheduled monument) is a register entry about the fort itself, and Devon County Council describes the same fort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3a229dc1-93fd-4ff5-93a9-6c3c61cc9e22'::uuid, 'site_type', 'Palace', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s003-rollback:3a229dc1-93fd-4ff5-93a9-6c3c61cc9e22:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Residence/villa/farmhouse'' restored on Zominthos', '[{"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=28244", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=28244", "quote": "The use of the palace of Zominthos is inextricably linked with the Sacred Cave, Idaean Cave", "outcome": "found"}, {"source": "https://www.hh.gr/en/destinations/zominthos/", "url": "https://www.hh.gr/en/destinations/zominthos/", "quote": "the Palace of Zominthos has recently been inscribed onto the UNESCO World Heritage List", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture site page (a unique Minoan palatial center) and the Hellenic Heritage guide both call the archaeological site at Zominthos, on the Psiloritis foothills, a palace and it is inscribed with the Minoan Palatial Centres; only one page (minoancrete.com) calls its central building a country house, so the stored residence/villa/farmhouse is not the sources'' description.", "value_page": null}]'::jsonb),
    ('3a28b216-d9f2-410d-a12e-050fc4759a98'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Odeon_Theater_(Amman)', 'https://en.wikipedia.org/wiki/Odeon_theater_(Amman)', 'fields-wd1-2026-09-26b-s003-rollback:3a28b216-d9f2-410d-a12e-050fc4759a98:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Odeon_theater_(Amman)'' restored on Odeon Theatre', '[{"source": "https://en.wikipedia.org/wiki/Odeon_Theater_(Amman)", "url": "https://en.wikipedia.org/wiki/Odeon_Theater_(Amman)", "quote": "Odeon Theater (Amman)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Odeon_Theater_(Amman)", "url": "https://en.wikipedia.org/wiki/Odeon_Theater_(Amman)", "quote": "The Odeon is a small 500-seat theatre in", "outcome": "found"}, {"source": "https://doa.gov.jo/EN/ListDetails/Archeological_Sites/1157/2", "url": "https://doa.gov.jo/EN/ListDetails/Archeological_Sites/1157/2", "quote": "Archaeological Site: The Small Theatre (The Odeon)", "outcome": "found"}, {"source": "https://tourlandmarks.com/landmarks-odeon-theatre_amman", "url": "https://tourlandmarks.com/landmarks-odeon-theatre_amman", "quote": "Odeon Theatre, Amman, Jordan, Asia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect; the article itself is ''Odeon Theater (Amman)'', about this odeon beside Amman''s Roman Theatre, which the Department of Antiquities lists as the Small Theatre (the Odeon) and Tourist Landmarks as the Odeon Theatre, Amman.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Odeon Theater (Amman)", "unreadable": false, "wikibase_item": "Q20422619"}}]'::jsonb),
    ('3a5d5834-888a-458f-8a4b-66c709340688'::uuid, 'site_type', 'Fortification', 'Settlement', 'fields-wd1-2026-09-26b-s003-rollback:3a5d5834-888a-458f-8a4b-66c709340688:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Settlement'' restored on Kraku Lu Jordan', '[{"source": "https://en.wikipedia.org/wiki/Kraku_Lu_Jordan", "url": "https://en.wikipedia.org/wiki/Kraku_Lu_Jordan", "quote": "It was a fortified establishment that to the east side had a wall that is 2 m of width", "outcome": "found"}, {"source": "https://docslib.org/doc/3001571/the-traces-of-roman-metallurgy-in-eastern-serbia", "url": "https://docslib.org/doc/3001571/the-traces-of-roman-metallurgy-in-eastern-serbia", "quote": "Kraku lu Jordan, plan of the fortification at the confluence of Brodica and Pek", "outcome": "found"}, {"source": "https://spomenicikulture.rs/rudarsko-metalur-ki-kompleks-kraku-lu-jordan/", "url": "https://spomenicikulture.rs/rudarsko-metalur-ki-kompleks-kraku-lu-jordan/", "quote": "Са севера, истока и делимично са југа утврђење је било природно заштићено речним токовима", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0125)", "decision": "replace", "status": "MISSING", "reasoning": "The sources describe a walled late Roman metallurgical works with towers and a gate: Wikipedia calls it a fortified establishment, S. Petkovic''s paper on Roman metallurgy in eastern Serbia shows the plan of the fortification and the heritage institute calls it an ''utvrdjenje'' (fortification). None calls it a settlement, and it processed ore rather than being a mine, so Fortification replaces Settlement.", "value_page": null}]'::jsonb),
    ('3a86a102-9b92-4f11-8dcf-4230d3534858'::uuid, 'source_url', 'https://digitalkarnak.ucsc.edu/Ramesses-III-Temple/', 'https://en.wikipedia.org/wiki/Mortuary_Temple_of_Ramesses_III', 'fields-wd1-2026-09-26b-s003-rollback:3a86a102-9b92-4f11-8dcf-4230d3534858:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Mortuary_Temple_of_Ramesses_III'' restored on Ramesses III Temple', '[{"source": "https://digitalkarnak.ucsc.edu/Ramesses-III-Temple/", "url": "https://digitalkarnak.ucsc.edu/Ramesses-III-Temple/", "quote": "Ramesses III constructed a new bark shrine south of the second pylon, enclosed by the later Shoshenq I court.", "outcome": "found"}, {"source": "https://madainproject.com/temple_of_ramesses_iii_at_karnak", "url": "https://madainproject.com/temple_of_ramesses_iii_at_karnak", "quote": "The Temple of Ramesses III, also known as the Barque Temple of Ramesses III, is a barque-chapel complex, located south of the second pylon of the Karnak Temple.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL redirects to Medinet Habu, Ramesses III''s mortuary temple on the west bank, not this barque temple in the Karnak forecourt; the site has no Wikipedia article, so the page about it is UCSC''s Digital Karnak entry, and the Madain Project describes the same temple south of the second pylon.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3b512b0e-f4d7-4d81-8467-87796cdf405a'::uuid, 'site_type', 'Settlement', 'Mound/tumulus', 'fields-wd1-2026-09-26b-s003-rollback:3b512b0e-f4d7-4d81-8467-87796cdf405a:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Mound/tumulus'' restored on Burgstallkogel, Sulm Valley', '[{"source": "https://en.wikipedia.org/wiki/Burgstallkogel", "url": "https://en.wikipedia.org/wiki/Burgstallkogel", "quote": "The hill hosted a significant settlement of trans-regional importance from 800 BC to about 600 BC.", "outcome": "found"}, {"source": "https://archaeoregion.at/en/the-burgstallkogel-near-grossklein-and-the-sulmtal-necropolis/", "url": "https://archaeoregion.at/en/the-burgstallkogel-near-grossklein-and-the-sulmtal-necropolis/", "quote": "With almost 700 preserved burial mounds surrounding a hilltop settlement on the summit of the Burgstallkogel", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Burgstallkogel site is the late Urnfield/Hallstatt hilltop settlement on the summit; the tumuli are the separately named Sulmtal necropolis surrounding it, so Settlement is the type that describes this site rather than Mound/tumulus.", "value_page": null}]'::jsonb),
    ('3b512b0e-f4d7-4d81-8467-87796cdf405a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Burgstallkogel', 'https://en.wikipedia.org/wiki/Burgstallkogel_(Sulm_valley)', 'fields-wd1-2026-09-26b-s003-rollback:3b512b0e-f4d7-4d81-8467-87796cdf405a:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Burgstallkogel_(Sulm_valley)'' restored on Burgstallkogel, Sulm Valley', '[{"source": "https://en.wikipedia.org/wiki/Burgstallkogel", "url": "https://en.wikipedia.org/wiki/Burgstallkogel", "quote": "The Burgstallkogel settlement itself was not fortified", "outcome": "found"}, {"source": "https://archaeoregion.at/der-burgstallkogel-bei-grossklein/", "url": "https://archaeoregion.at/der-burgstallkogel-bei-grossklein/", "quote": "Der Burgstallkogel bei Großklein gehört zu den prominentesten archäologischen Fundstellen der ausgehenden Spätbronze- und der älteren Eisenzeit in Europa (9.–6. Jh. v. Chr.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect to the English Wikipedia article Burgstallkogel, which treats the hill''s Hallstatt settlement and necropolis; the article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Burgstallkogel", "unreadable": false, "wikibase_item": "Q4998727"}}]'::jsonb),
    ('3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Mycenaean Acropolis of Midea', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5800) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e'::uuid, 'period_start', '-5800', '-4000', 'fields-wd1-2026-09-26b-s003-rollback:3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4000'' restored on Mycenaean Acropolis of Midea', '[{"source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1", "quote": "The earliest material found at Midea consist of pottery from the Middle and Final Neolithic periods (c. 5800–3100 BC).", "outcome": "found"}, {"source": "https://madainproject.com/acropolis_of_midea", "url": "https://madainproject.com/acropolis_of_midea", "quote": "Archaeological evidence reveals that the hill-site of Midea was occupied continuously from the late or final Neolithic (circa 4800–3100 BCE)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "MISSING", "reasoning": "The Swedish Institute at Athens, co-excavator of Midea, dates the earliest material to the Middle Neolithic from c. 5800 BC, and Madain Project dates the first occupation to c. 4800 BC; both put the start before 4500 BC, not in the stored 4500-3000 BC bucket, and the excavators'' c. 5800 BC is taken.", "value_page": null}]'::jsonb),
    ('3bb2d9e1-7e77-4582-8b28-92ab27133a9a'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3bb2d9e1-7e77-4582-8b28-92ab27133a9a:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Wandlebury Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3bb2d9e1-7e77-4582-8b28-92ab27133a9a'::uuid, 'period_start', '-400', '-1000', 'fields-wd1-2026-09-26b-s003-rollback:3bb2d9e1-7e77-4582-8b28-92ab27133a9a:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Wandlebury Hill', '[{"source": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "url": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "quote": "The first hillfort was constructed in about 400 BC", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4545", "url": "https://www.megalithic.co.uk/article.php?sid=4545", "quote": "In the 3rd century BCE, only the outer ditch and rampart defended the site.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the first hillfort to about 400 BC and the Megalithic Portal places the first single-rampart phase in the 3rd century BCE (the Prehistoric Society''s signpost has the 1955-6 excavations dating first construction to the 4th century BC). The start therefore lies in 500 BC - 1 AD, not in the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('3bb2d9e1-7e77-4582-8b28-92ab27133a9a'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:3bb2d9e1-7e77-4582-8b28-92ab27133a9a:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Wandlebury Hill', '[{"source": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "url": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "quote": "Iron Age hill fort in Cambridgeshire", "outcome": "found"}, {"source": "https://cambridgeppf.org/history-of-wandlebury/", "url": "https://cambridgeppf.org/history-of-wandlebury/", "quote": "This was altered in the later Iron Age into a large multivallate hillfort (the fort was protected by two ditches).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the site''s owner Cambridge Past, Present & Future both describe Wandlebury as an Iron Age hill fort; Fort is the most specific canonical type for a hillfort.", "value_page": null}]'::jsonb),
    ('3bb2d9e1-7e77-4582-8b28-92ab27133a9a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort', 'https://en.wikipedia.org/wiki/Wandlebury_Hill', 'fields-wd1-2026-09-26b-s003-rollback:3bb2d9e1-7e77-4582-8b28-92ab27133a9a:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Wandlebury_Hill'' restored on Wandlebury Hill', '[{"source": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "url": "https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort", "quote": "Wandlebury Hill Fort, also known as the Wandlebury Ring, is an Iron Age hillfort located on Wandlebury Hill in the Gog Magog Hills, Cambridgeshire, England, to the southeast of Cambridge.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4545", "url": "https://www.megalithic.co.uk/article.php?sid=4545", "quote": "Site Name: Wandlebury Alternative Name: Wandlebury Ring", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the hill (a peak and country park); English Wikipedia has a separate article on the hill fort itself, Wandlebury Hill Fort, which the Megalithic Portal entry for the same site confirms by name.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Wandlebury Hill Fort", "unreadable": false, "wikibase_item": "Q7967271"}}]'::jsonb),
    ('3c466fde-b751-4065-8de2-bd5c9280afe5'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Viso%C4%8Dica_(hill)', 'https://en.wikipedia.org/wiki/Bosnian_pyramid_claims', 'fields-wd1-2026-09-26b-s003-rollback:3c466fde-b751-4065-8de2-bd5c9280afe5:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Bosnian_pyramid_claims'' restored on Bosnian Pyramid of the Sun', '[{"source": "https://en.wikipedia.org/wiki/Viso%C4%8Dica_(hill)", "url": "https://en.wikipedia.org/wiki/Viso%C4%8Dica_(hill)", "quote": "Visočica hill came to international attention in October 2005, following a campaign to promote the scientifically unsupported idea that it is the largest of a group of ancient man-made", "outcome": "found"}, {"source": "https://ancientworldatlas.com/sites/bosnian-pyramid-of-the-sun", "url": "https://ancientworldatlas.com/sites/bosnian-pyramid-of-the-sun", "quote": "Bosnian ''Pyramid of the Sun'' (Visočica Hill)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ''Bosnian Pyramid of the Sun'' is Visočica hill itself (Ancient World Atlas: ''Bosnian Pyramid of the Sun (Visočica Hill)''); the English Wikipedia article Visočica (hill) is the site''s own article (Wikidata Q797511) and covers the pyramid claim about it, while the stored ''Bosnian pyramid claims'' article is about the whole group of claimed pyramids.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Visočica (hill)", "unreadable": false, "wikibase_item": "Q797511"}}]'::jsonb),
    ('3c47ded2-01b0-4789-bf6e-defb171ddd43'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:3c47ded2-01b0-4789-bf6e-defb171ddd43:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Midea, Argolid', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4800) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3c47ded2-01b0-4789-bf6e-defb171ddd43'::uuid, 'period_start', '-4800', '-4000', 'fields-wd1-2026-09-26b-s003-rollback:3c47ded2-01b0-4789-bf6e-defb171ddd43:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4000'' restored on Midea, Argolid', '[{"source": "https://madainproject.com/acropolis_of_midea", "url": "https://madainproject.com/acropolis_of_midea", "quote": "Archaeological evidence reveals that the hill-site of Midea was occupied continuously from the late or final Neolithic (circa 4800–3100 BCE) and into the Early Bronze Age (Early Helladic I–II, circa 3100–2200 BCE).", "outcome": "found"}, {"source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1", "quote": "The earliest material found at Midea consist of pottery from the Middle and Final Neolithic periods (c. 5800–3100 BC).", "outcome": "found"}, {"source": "https://aspel.gr/midea.html", "url": "https://aspel.gr/midea.html", "quote": "The hill on which Midea is built was already occupied by the late Neolithic period (5th to 4th Millenia BC) and by the early and middle Bronze Age had developed into a flourishing settlement.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "MISSING", "reasoning": "Occupation of the Midea hill begins in the Late Neolithic, dated circa 4800 BCE by the Madain Project and the 5th millennium BC by aspel.gr, while the excavators (Swedish Institute at Athens) report earliest pottery of the Middle and Final Neolithic (c. 5800–3100 BC); every source puts the start before 4500 BC, not in the stored bucket 4500 - 3000 BC.", "value_page": null}]'::jsonb),
    ('3c579791-33d8-46bd-90da-1551035cc419'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:3c579791-33d8-46bd-90da-1551035cc419:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Carrawburgh', '[{"source": "https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/", "url": "https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/", "quote": "Carrawburgh – known to the Romans as Brocolitia – was one of 16 large forts along Hadrian’s Wall.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Carrawburgh", "url": "https://en.wikipedia.org/wiki/Carrawburgh", "quote": "auxiliary fort on Hadrian''s Wall called Brocolitia, Procolita, or Brocolita.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site at Carrawburgh is the Roman auxiliary fort Brocolitia on Hadrian''s Wall (with its vicus and temples); English Heritage and Wikipedia both call it a fort, so Fort replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('3c612fb4-3639-4124-8e26-58457c82376a'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:3c612fb4-3639-4124-8e26-58457c82376a:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Beinan Cultural Park', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3c612fb4-3639-4124-8e26-58457c82376a'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s003-rollback:3c612fb4-3639-4124-8e26-58457c82376a:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4000'' restored on Beinan Cultural Park', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0139)", "decision": "clear", "status": "MISSING", "reasoning": "Every source found dates the site only in years before present: Chinese Wikipedia gives 5300 to 2300 years ago and the Bureau of Cultural Heritage page gives about 2,000 to 5,000 years ago. No source states a BC year, century or millennium for its first occupation, so the start cannot be quoted and the field is cleared.", "value_page": null}]'::jsonb),
    ('3c612fb4-3639-4124-8e26-58457c82376a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Peinan_Site_Park', 'https://en.wikipedia.org/wiki/Beinan_Cultural_Park', 'fields-wd1-2026-09-26b-s003-rollback:3c612fb4-3639-4124-8e26-58457c82376a:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Beinan_Cultural_Park'' restored on Beinan Cultural Park', '[{"source": "https://en.wikipedia.org/wiki/Peinan_Site_Park", "url": "https://en.wikipedia.org/wiki/Peinan_Site_Park", "quote": "Peinan Site Park (traditional Chinese: 卑南遺址公園; simplified Chinese: 卑南遺址公园; pinyin: Pēinán Yízhǐ Gōngyuán) is an archeological site in Taitung City, Taitung County, Taiwan.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23475", "url": "https://www.megalithic.co.uk/article.php?sid=23475", "quote": "Today, the Peinan site (Beinan site) is recognized as the largest and most intact Neolithic village of its kind in the Pacific Basin.", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Beinan_Cultural_Park URL is only a redirect to the English article Peinan Site Park, which is the article of this archaeological park (Beinan Cultural Park, Taitung, at 22.794N 121.116E, matching the stored point); the Megalithic Portal entry for the same park (also listed as Peinan Cultural Park, same coordinates) independently names the Peinan/Beinan site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Peinan Site Park", "unreadable": false, "wikibase_item": "Q16241459"}}]'::jsonb),
    ('3cb40a58-d0d1-4094-bb78-2398d60dbd5c'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3cb40a58-d0d1-4094-bb78-2398d60dbd5c:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Tomb of the Birds', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3cb40a58-d0d1-4094-bb78-2398d60dbd5c'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s003-rollback:3cb40a58-d0d1-4094-bb78-2398d60dbd5c:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Tomb of the Birds', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "clear", "status": "MISSING", "reasoning": "The tomb''s date is not established. Digital Giza records only W. S. Smith''s 1946 pencil note that he ''had the idea'' it was an 18th Dynasty or New Kingdom tomb, Ancient Wisdom calls it ''generally accepted'' as Old Kingdom without a year, and the bird burials belong to later reuse. No two independent sources securely date its start.", "value_page": null}]'::jsonb),
    ('3cb40a58-d0d1-4094-bb78-2398d60dbd5c'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s003-rollback:3cb40a58-d0d1-4094-bb78-2398d60dbd5c:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Necropolis/tombs complex'' restored on Tomb of the Birds', '[{"source": "https://giza.fas.harvard.edu/sites/4158/full/", "url": "https://giza.fas.harvard.edu/sites/4158/full/", "quote": "Rock-cut tomb in far Western Cemetery, one of three numbered \"North Cliff\" tombs.", "outcome": "found"}, {"source": "https://www.andrewcollins.com/page/articles/sealed.htm", "url": "https://www.andrewcollins.com/page/articles/sealed.htm", "quote": "The move follows recent work to clear the interior of the tomb known as NC2 or the \"Tomb of the Birds\", and located in the plateau''s north cliff.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "MISSING", "reasoning": "Harvard''s Digital Giza catalogues NC 2 as a single rock-cut tomb, and Andrew Collins describes the Tomb of the Birds as the tomb known as NC2. It is one tomb, reused for bird burials, not a necropolis of many tombs, so Tomb is the most specific type.", "value_page": null}]'::jsonb),
    ('3cb40a58-d0d1-4094-bb78-2398d60dbd5c'::uuid, 'source_url', 'https://giza.fas.harvard.edu/sites/4158/full/', 'https://pocketsights.com/tours/place/Tomb-of-the-Birds-41831:4903', 'fields-wd1-2026-09-26b-s003-rollback:3cb40a58-d0d1-4094-bb78-2398d60dbd5c:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://pocketsights.com/tours/place/Tomb-of-the-Birds-41831:4903'' restored on Tomb of the Birds', '[{"source": "https://giza.fas.harvard.edu/sites/4158/full/", "url": "https://giza.fas.harvard.edu/sites/4158/full/", "quote": "Rock-cut tomb in far Western Cemetery, one of three numbered \"North Cliff\" tombs.", "outcome": "found"}, {"source": "https://www.andrewcollins.com/page/articles/sealed.htm", "url": "https://www.andrewcollins.com/page/articles/sealed.htm", "quote": "The move follows recent work to clear the interior of the tomb known as NC2 or the \"Tomb of the Birds\", and located in the plateau''s north cliff.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored PocketSights page returns 404. Harvard''s Digital Giza entry ''NC 2'' is the scholarly catalogue page for this very tomb, and Andrew Collins'' article confirms that NC2 is the tomb called the Tomb of the Birds.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
