    ('3cc112fa-e1fc-420a-8089-1a9db46cddbf'::uuid, 'period_start', '-3000', '-4000', 'fields-wd1-2026-09-26b-s003-rollback:3cc112fa-e1fc-420a-8089-1a9db46cddbf:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4000'' restored on Kamares, Crete', '[{"source": "https://de.wikipedia.org/wiki/Kamares-H%C3%B6hle", "url": "https://de.wikipedia.org/wiki/Kamares-H%C3%B6hle", "quote": "Die aufgefundene Keramik zeigt, dass die Höhle während einer Zeit von etwa 3000 v. Chr. bis 1100 v. Chr. besucht wurde.", "outcome": "found"}, {"source": "https://www.showcaves.com/english/gr/caves/Kamares.html", "url": "https://www.showcaves.com/english/gr/caves/Kamares.html", "quote": "The cave was visited during all periods of the Bronze Age, from 3000 to 1100 BC.", "outcome": "found"}, {"source": "https://www.cretanbeaches.com/en/caves/kamares-cave", "url": "https://www.cretanbeaches.com/en/caves/kamares-cave", "quote": "Pottery dating back in 2000 BC was found, used, possibly by the residents of Phaestus, for worshiping a Minoan goddess.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "MISSING", "reasoning": "The pottery from the cave dates its use from c. 3000 BC (start of the Bronze Age) to 1100 BC, with the Kamares-ware cult deposits around 2000 BC; the stored 4000 BC is not supported by any dated source, so the start becomes c. 3000 BC.", "value_page": null}]'::jsonb),
    ('3cc112fa-e1fc-420a-8089-1a9db46cddbf'::uuid, 'site_type', 'Cave', 'Cave Structures', 'fields-wd1-2026-09-26b-s003-rollback:3cc112fa-e1fc-420a-8089-1a9db46cddbf:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Cave Structures'' restored on Kamares, Crete', '[{"source": "https://en.wikipedia.org/wiki/Kamares,_Crete", "url": "https://en.wikipedia.org/wiki/Kamares,_Crete", "quote": "It is the location of the archaeological site of Kamares Cave, a Minoan sacred cave.", "outcome": "found"}, {"source": "https://www.unescositesincrete.gr/en/simeia-endiaferontos/kamares-cave/", "url": "https://www.unescositesincrete.gr/en/simeia-endiaferontos/kamares-cave/", "quote": "The cave is located northeast of Kamares, to the south of Psiloritis, on the slopes of Mount Soros at an altitude of 1700m.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a natural cave used as a Minoan sacred cave, without built structures; Cave is the type the sources name.", "value_page": null}]'::jsonb),
    ('3cc112fa-e1fc-420a-8089-1a9db46cddbf'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Kamares-H%C3%B6hle', 'https://en.wikipedia.org/wiki/Kamares,_Crete', 'fields-wd1-2026-09-26b-s003-rollback:3cc112fa-e1fc-420a-8089-1a9db46cddbf:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Kamares,_Crete'' restored on Kamares, Crete', '[{"source": "https://de.wikipedia.org/wiki/Kamares-H%C3%B6hle", "url": "https://de.wikipedia.org/wiki/Kamares-H%C3%B6hle", "quote": "Die Kamares-Höhle befindet sich in 1524 Meter Höhe am südlichen Abhang des Psiloritis-Gebirges auf der Insel Kreta.", "outcome": "found"}, {"source": "https://www.unescositesincrete.gr/en/simeia-endiaferontos/kamares-cave/", "url": "https://www.unescositesincrete.gr/en/simeia-endiaferontos/kamares-cave/", "quote": "The cave is located northeast of Kamares, to the south of Psiloritis, on the slopes of Mount Soros at an altitude of 1700m.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is the village''s (English Wikipedia''s Kamares Cave title redirects to it); German Wikipedia has an article on the Kamares Cave itself.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Kamares-Höhle", "unreadable": false, "wikibase_item": "Q2738464"}}]'::jsonb),
