    ('3d5ee71b-22cf-4781-9432-e4f275543a7d'::uuid, 'site_type', NULL, 'Earthwork', 'fields-wd1-2026-09-26b-s003-rollback:3d5ee71b-22cf-4781-9432-e4f275543a7d:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Earthwork'' restored on Jaw Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0037)", "decision": "clear", "status": "CONFLICT", "reasoning": "The single source, the Wikipedia article on the hill, calls the site a large square cropmark enclosure once thought to be a possible Roman marching camp; no independent second source says what kind of site it is, so the type cannot be confirmed.", "value_page": null}]'::jsonb),
    ('3d5ee71b-22cf-4781-9432-e4f275543a7d'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Jaw_Hill', 'fields-wd1-2026-09-26b-s003-rollback:3d5ee71b-22cf-4781-9432-e4f275543a7d:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Jaw_Hill'' restored on Jaw Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0037)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored page is the Wikipedia article on the hill Jaw Hill, whose one history paragraph describes the enclosure; its cited Archaeology Data Service record is a generic link behind a bot challenge, and every other page found is a copy of the Wikipedia text, so no page about this very site can be corroborated by an independent source family.", "value_page": null}]'::jsonb),
    ('3d8cb484-8b57-41fa-ab0d-203449c1c821'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:3d8cb484-8b57-41fa-ab0d-203449c1c821:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Burrington Combe', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3d8cb484-8b57-41fa-ab0d-203449c1c821'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s003-rollback:3d8cb484-8b57-41fa-ab0d-203449c1c821:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4500'' restored on Burrington Combe', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "The sources give the combe''s first occupation only as the Upper Palaeolithic or in years before present (Aveline''s Hole burials ''between roughly 10,200 and 10,400 years old''); none states a BC year, century or millennium, and the stored 4500 - 3000 BC bucket is contradicted, so the field is emptied.", "value_page": null}]'::jsonb),
    ('3db38675-ded2-42a9-968f-b22744e5faff'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:3db38675-ded2-42a9-968f-b22744e5faff:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Scholes Coppice', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3db38675-ded2-42a9-968f-b22744e5faff'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:3db38675-ded2-42a9-968f-b22744e5faff:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Scholes Coppice', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "clear", "status": "MISSING", "reasoning": "No two sources date the start: the Wikidata item gives start time ''unknown value'', the South Yorkshire HER calls it a monument of unknown date, and the Megalithic Portal only gives a range (750 BCE to 42 CE); nothing supports the stored 1 AD.", "value_page": null}]'::jsonb),
    ('3db38675-ded2-42a9-968f-b22744e5faff'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:3db38675-ded2-42a9-968f-b22744e5faff:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Scholes Coppice', '[{"source": "https://en.wikipedia.org/wiki/Scholes_Coppice", "url": "https://en.wikipedia.org/wiki/Scholes_Coppice", "quote": "the most significant of which is thought to be an Iron Age hill fort", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5168", "url": "https://www.megalithic.co.uk/article.php?sid=5168", "quote": "Hillfort in South Yorkshire", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal describe Caesar''s Camp as an Iron Age hill fort, a small banked and ditched enclosure, not a fortress or citadel; Fort is the most specific type.", "value_page": null}]'::jsonb),
    ('3db38675-ded2-42a9-968f-b22744e5faff'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=5168', 'https://en.wikipedia.org/wiki/Scholes_Coppice', 'fields-wd1-2026-09-26b-s003-rollback:3db38675-ded2-42a9-968f-b22744e5faff:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Scholes_Coppice'' restored on Scholes Coppice', '[{"source": "https://www.megalithic.co.uk/article.php?sid=5168", "url": "https://www.megalithic.co.uk/article.php?sid=5168", "quote": "The ramparts at Caesar''s Camp (who named it thus?), Scholes Coppice.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Scholes_Coppice", "url": "https://en.wikipedia.org/wiki/Scholes_Coppice", "quote": "Known as Caesar''s Camp or Castle Holmes, this Scheduled Ancient Monument was partially excavated in the 1990s.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the woodland that contains the fort; there is no Wikipedia article on the hillfort itself, and the Historic England entry cannot be read by the checker, so the Megalithic Portal page on the Scholes Wood hillfort (Caesar''s Camp) is the readable page about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3debd642-ff96-4840-bff2-9d8faced25cd'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:3debd642-ff96-4840-bff2-9d8faced25cd:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Eggardon Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3debd642-ff96-4840-bff2-9d8faced25cd'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s003-rollback:3debd642-ff96-4840-bff2-9d8faced25cd:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4500'' restored on Eggardon Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Dorset HER only say the multivallate hillfort is of Iron Age date (the HER files it under its generic ''Iron Age - 800 BC to 42 AD'' period); earlier finds (Neolithic flints, Bronze Age linear earthworks and barrows) precede the fort. No source gives a construction or first-occupation year, and the Iron Age spans two buckets, so the stored Neolithic -4500 cannot be kept or replaced.", "value_page": null}]'::jsonb),
    ('3debd642-ff96-4840-bff2-9d8faced25cd'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:3debd642-ff96-4840-bff2-9d8faced25cd:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Eggardon Hill', '[{"source": "https://en.wikipedia.org/wiki/Eggardon_Hill", "url": "https://en.wikipedia.org/wiki/Eggardon_Hill", "quote": "Eggardon Hill is a prehistoric hillfort on a hill in Dorset, England.", "outcome": "found"}, {"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO95", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO95", "quote": "(12) EGGARDON CAMP, hill-fort (Plate 71), partly in Powerstock parish, occupies the summit of a hill 800 ft. high", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Dorset Historic Environment Record (quoting the RCHME inventory) both describe Eggardon as a hill-fort, a fortified enclosure; Fort is the canonical type that names that, not a fortress or citadel.", "value_page": null}]'::jsonb),
    ('3e012d60-1be3-49b9-83a2-7e1edeab0d77'::uuid, 'geom', 'SRID=4326;POINT(23.1617 37.6331)', '0101000020E6100000EB38B84D121337407343414689CC4240', 'fields-wd1-2026-09-26b-s003-rollback:3e012d60-1be3-49b9-83a2-7e1edeab0d77:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E6100000EB38B84D121337407343414689CC4240'' restored on Epidaurus', '[{"source": "https://topostext.org/place/376232PEpi", "url": "https://topostext.org/place/376232PEpi", "quote": "Latitude: 37.633100 Longitude: 23.161700", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/21954.html", "url": "https://imperium.ahlfeldt.se/places/21954.html", "quote": "37.633674, 23.160403", "outcome": "found"}, {"source": "http://nomisma.org/id/epidaurus", "url": "http://nomisma.org/id/epidaurus", "quote": "Latitude 37.633280 Longitude 23.160067", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "CONFLICT", "reasoning": "This entry is the ancient city (polis) of Epidaurus, not its Sanctuary of Asklepios (a separate entry): ToposText (''Coastal polis with walls and theater at Archaia Epidauros''), the Digital Atlas of the Roman Empire and Nomisma all place the city at Palaia Epidavros, about 37.633, 23.161; the stored point is the sanctuary 8.5 km inland, so it is replaced.", "value_page": null}]'::jsonb),
