    ('3e012d60-1be3-49b9-83a2-7e1edeab0d77'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3e012d60-1be3-49b9-83a2-7e1edeab0d77:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Epidaurus', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3e012d60-1be3-49b9-83a2-7e1edeab0d77'::uuid, 'period_start', '-3000', '-1500', 'fields-wd1-2026-09-26b-s003-rollback:3e012d60-1be3-49b9-83a2-7e1edeab0d77:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Epidaurus', '[{"source": "https://visitpeloponnese.com/en/prdct/old-palea-epidaurus", "url": "https://visitpeloponnese.com/en/prdct/old-palea-epidaurus", "quote": "It is believed that the ancient city of Epidaurus was inhabited from the 3rd millennium BC, but it has not been systematically excavated.", "outcome": "found"}, {"source": "https://www.allovergreece.com/el/beautiful-greek-villages/palaia-epidavros", "url": "https://www.allovergreece.com/el/beautiful-greek-villages/palaia-epidavros", "quote": "Αρχαιολογικά ευρήματα αποδεικνύουν την κατοίκηση από την 3η π.Χ. χιλιετία.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "MISSING", "reasoning": "The Peloponnese region''s tourism portal and All Over Greece (archaeological finds prove habitation from the 3rd millennium BC) date the first occupation of the city site at Palaia Epidavros to the 3rd millennium BC, as do Greek Wikipedia (Early Helladic remains) and an EGU 2010 abstract co-written by the Argolid ephorate; this lies in 3000 - 1500 BC, before the 15th-century BC Mycenaean necropolis, so -1500 is replaced by -3000.", "value_page": null}]'::jsonb),
    ('3e0ef472-929c-4669-ad45-c7a19c78d25f'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3e0ef472-929c-4669-ad45-c7a19c78d25f:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Lower Swat Valley', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3e0ef472-929c-4669-ad45-c7a19c78d25f'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:3e0ef472-929c-4669-ad45-c7a19c78d25f:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Lower Swat Valley', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "clear", "status": "MISSING", "reasoning": "The pages about the Lower Swat Valley only say it ''has been occupied for the last 3000 years'' (a years-ago figure) and date single sites within it (Aligrama to 1000 BC); for a region spanning many sites no two independent sources state one start year, so the field is emptied.", "value_page": null}]'::jsonb),
    ('3e0ef472-929c-4669-ad45-c7a19c78d25f'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:3e0ef472-929c-4669-ad45-c7a19c78d25f:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Lower Swat Valley', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "clear", "status": "CONFLICT", "reasoning": "The sources describe the Lower Swat Valley as an area holding many archaeological sites (Gandhara graves, stupas, Shahi buildings) around Barikot, Udegram and Saidu Sharif, not as a city, town or settlement; no two independent sources assign it one kind of site, so the wrong ''City/town/settlement'' is emptied.", "value_page": null}]'::jsonb),
    ('3e0ef472-929c-4669-ad45-c7a19c78d25f'::uuid, 'source_url', 'https://ur.wikipedia.org/wiki/%D8%B2%DB%8C%D8%B1%DB%8C%DA%BA_%D8%B3%D9%88%D8%A7%D8%AA_%D9%88%D8%A7%D8%AF%DB%8C', 'https://en.wikipedia.org/wiki/Lower_Swat_Valley', 'fields-wd1-2026-09-26b-s003-rollback:3e0ef472-929c-4669-ad45-c7a19c78d25f:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Lower_Swat_Valley'' restored on Lower Swat Valley', '[{"source": "https://ur.wikipedia.org/wiki/%D8%B2%DB%8C%D8%B1%DB%8C%DA%BA_%D8%B3%D9%88%D8%A7%D8%AA_%D9%88%D8%A7%D8%AF%DB%8C", "url": "https://ur.wikipedia.org/wiki/%D8%B2%DB%8C%D8%B1%DB%8C%DA%BA_%D8%B3%D9%88%D8%A7%D8%AA_%D9%88%D8%A7%D8%AF%DB%8C", "quote": "زیریں سوات وادی سوات اور مالاکنڈ میں واقع ایک اہم تاریخی علاقہ ہے۔", "outcome": "found"}, {"source": "https://www.pakistanpaedia.com/land/swat/valleys-of-pakistan_swat.html", "url": "https://www.pakistanpaedia.com/land/swat/valleys-of-pakistan_swat.html", "quote": "The Lower Swat Valley has been occupied for the last 3000 years. The area between Chakdara Bridge and Saidu Sharif is littered with the remains of", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0018)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia''s Lower Swat Valley title is now only a redirect to the article on the whole Swat Valley (redirected on 14 April 2026), which is not about this area; the Urdu Wikipedia has its own article on the Lower Swat Valley (an important historical area in Swat and Malakand with Buddhist monastery remains at Saidu Sharif), and Pakistan Paedia independently describes the Lower Swat Valley as an area of archaeological sites between Chakdara Bridge and Saidu Sharif.", "value_page": {"lang": "ur", "problem": null, "resolved_title": "زیریں سوات وادی", "unreadable": false, "wikibase_item": "Q6693857"}}]'::jsonb),
    ('3e25aa3a-9fb4-4e40-9989-07039d798515'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:3e25aa3a-9fb4-4e40-9989-07039d798515:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on Agrour Amogjar', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3e25aa3a-9fb4-4e40-9989-07039d798515'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s003-rollback:3e25aa3a-9fb4-4e40-9989-07039d798515:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on Agrour Amogjar', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0093)", "decision": "clear", "status": "MISSING", "reasoning": "The paintings are dated only in relative or before-present terms (Vernet 2006: ''pastoral'' period to recent graffiti, pendant-bearing cattle in the 4th millennium BP; the British Museum: ''could be more than 5,000 years old''); no source gives a calendar start for the site, and nothing supports the stored 500 BC.", "value_page": null}]'::jsonb),
    ('3e483113-87b4-4219-86ef-cd56a034f8c8'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:3e483113-87b4-4219-86ef-cd56a034f8c8:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Ermita de la Virgen del Pilar Dam', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3e483113-87b4-4219-86ef-cd56a034f8c8'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:3e483113-87b4-4219-86ef-cd56a034f8c8:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Ermita de la Virgen del Pilar Dam', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and a tourism page give an older attribution to the 1st (or 2nd) century AD, but the 2023 Geoarchaeology study (Peña-Monné et al.), which dated charcoal from the dam''s mortars, puts the initial dam at ca. 100 BC - 10 AD, probably Augustan, i.e. mostly before 1 AD; that securely dated start rests on one source family only and lies across the bucket boundary from the stored value, so no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('3e483113-87b4-4219-86ef-cd56a034f8c8'::uuid, 'site_type', 'Reservoir/aqueduct/canal', 'Megalithic structures', 'fields-wd1-2026-09-26b-s003-rollback:3e483113-87b4-4219-86ef-cd56a034f8c8:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic structures'' restored on Ermita de la Virgen del Pilar Dam', '[{"source": "https://portalcientifico.uam.es/en/ipublic/item/9225888", "url": "https://portalcientifico.uam.es/en/ipublic/item/9225888", "quote": "The Monforte de Moyuela dam, also known as Ermita de la Virgen del Pilar dam, is a Roman reservoir built on a tributary of the Aguasvivas River (Ebro basin, Spain).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Pilar_Dam", "url": "https://en.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Pilar_Dam", "quote": "is a Roman gravity dam in Teruel province", "outcome": "found"}, {"source": "https://quickclick.es/rop/detalle_articulo.php?registro=18422&numero_revista=3456&anio=2005&anio_ini=2020&anio_fin=2020", "url": "https://quickclick.es/rop/detalle_articulo.php?registro=18422&numero_revista=3456&anio=2005&anio_ini=2020&anio_fin=2020", "quote": "The Ermita del Pilar dam is another good example of the numerous dams constructed by the Romans in Spain.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "All sources describe the site as a Roman gravity dam that impounded a reservoir on the río Santa María, not a megalithic structure; Reservoir/aqueduct/canal is the most specific canonical type for a Roman dam and its reservoir.", "value_page": null}]'::jsonb),
    ('3ea6db8c-1b6a-4880-a954-b929302e8260'::uuid, 'site_type', 'Wall', 'Fortress', 'fields-wd1-2026-09-26b-s003-rollback:3ea6db8c-1b6a-4880-a954-b929302e8260:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress'' restored on Hadnmauer', '[{"source": "https://commons.wikimedia.org/wiki/Category:Hadnmauer,_Hermagor", "url": "https://commons.wikimedia.org/wiki/Category:Hadnmauer,_Hermagor", "quote": "Ancient Roman defensive walls", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Hadnmauer", "url": "https://en.wikipedia.org/wiki/Hadnmauer", "quote": "The Hadnmauer is the protected ruin of a letzi (defensive barrier across a valley) in the Gailtal valley in Austria", "outcome": "found"}, {"source": "https://www.krone.at/3916660", "url": "https://www.krone.at/3916660", "quote": "Gut erhaltene Reste einer mächtigen römischen Mauer aus den ersten Jahrhunderten wurden entdeckt!", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Hadnmauer is a 1.6 km Roman barrier wall (Talsperre, letzi) across the Gail valley, not a fortress and not a water dam: Wikimedia files it under ancient Roman defensive walls and describes it as a defensive barrier across a valley, and the Kronen Zeitung reports the excavated remains of a mighty Roman wall (Mauer).", "value_page": null}]'::jsonb),
    ('3f16cff5-f53f-4a81-9813-c80214933fd5'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:3f16cff5-f53f-4a81-9813-c80214933fd5:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Ayazini Kaya Church', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3f16cff5-f53f-4a81-9813-c80214933fd5'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:3f16cff5-f53f-4a81-9813-c80214933fd5:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Ayazini Kaya Church', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "clear", "status": "MISSING", "reasoning": "The dating of the church is disputed across buckets: the Ministry''s Kültür Portalı says it is thought to have been built in the 1000s and notes that some sources date it to the 8th-10th centuries, and Kültür Envanteri/ayazini.org give the 8th-10th century. No secure start can be stated, and the stored 1 AD is certainly wrong, so the field is emptied.", "value_page": null}]'::jsonb),
    ('3f16cff5-f53f-4a81-9813-c80214933fd5'::uuid, 'site_type', 'Church', 'Cave Structures', 'fields-wd1-2026-09-26b-s003-rollback:3f16cff5-f53f-4a81-9813-c80214933fd5:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Cave Structures'' restored on Ayazini Kaya Church', '[{"source": "https://turkisharchaeonews.net/site/ayazini", "url": "https://turkisharchaeonews.net/site/ayazini", "quote": "The main historical attraction of Ayazini is a church from the Byzantine period, partly carved into the rock.", "outcome": "found"}, {"source": "https://www.afyondayiz.gov.tr/sayfa-ayazini-kilisesi/", "url": "https://www.afyondayiz.gov.tr/sayfa-ayazini-kilisesi/", "quote": "İhsaniye ilçesi, Ayazini köyünün girişinde yol kenarında, tüf sarp kayalık içinde, kayaya oyulmuş bir kilisedir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Byzantine rock-cut church of Ayazini, a church building carved into the tuff, not a cave complex or a village; both sources describe it as a church.", "value_page": null}]'::jsonb),
    ('3f16cff5-f53f-4a81-9813-c80214933fd5'::uuid, 'source_url', 'https://www.afyondayiz.gov.tr/sayfa-ayazini-kilisesi/', 'https://en.wikipedia.org/wiki/Ayazini,_%C4%B0hsaniye', 'fields-wd1-2026-09-26b-s003-rollback:3f16cff5-f53f-4a81-9813-c80214933fd5:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Ayazini,_%C4%B0hsaniye'' restored on Ayazini Kaya Church', '[{"source": "https://www.afyondayiz.gov.tr/sayfa-ayazini-kilisesi/", "url": "https://www.afyondayiz.gov.tr/sayfa-ayazini-kilisesi/", "quote": "İhsaniye ilçesi, Ayazini köyünün girişinde yol kenarında, tüf sarp kayalık içinde, kayaya oyulmuş bir kilisedir.", "outcome": "found"}, {"source": "https://turkisharchaeonews.net/site/ayazini", "url": "https://turkisharchaeonews.net/site/ayazini", "quote": "The main historical attraction of Ayazini is a church from the Byzantine period, partly carved into the rock.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia page is the article on Ayazini village; the Afyonkarahisar culture and tourism directorate''s page ''Ayazini Kilisesi'' is about this very rock-cut church at the village entrance, which Turkish Archaeological News independently describes.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('3f170e16-175a-4e4c-9717-1f0e32d05e8e'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:3f170e16-175a-4e4c-9717-1f0e32d05e8e:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Appolonia Temple Ruins', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3f170e16-175a-4e4c-9717-1f0e32d05e8e'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:3f170e16-175a-4e4c-9717-1f0e32d05e8e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Appolonia Temple Ruins', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "clear", "status": "MISSING", "reasoning": "Kültür Envanteri types the structure only as ''?, Tapınak'' and gives no date; no source dates the construction of this particular building. The c. 500 BC date of Apollonia''s pillar tombs belongs to the city, not to this structure 4 km away.", "value_page": null}]'::jsonb),
    ('3f170e16-175a-4e4c-9717-1f0e32d05e8e'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Apollonia_(Lycia)', 'fields-wd1-2026-09-26b-s003-rollback:3f170e16-175a-4e4c-9717-1f0e32d05e8e:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Apollonia_(Lycia)'' restored on Appolonia Temple Ruins', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored page is the article on the ancient city of Apollonia (Lycia), whose ruins lie about 4 km from this structure, so it is not about this site. The only page about the structure itself is its Kültür Envanteri entry, and its Wikidata item is an import of that entry, so no second independent source family names it.", "value_page": null}]'::jsonb),
    ('3f793103-342f-40ca-a0fa-96b1065ad986'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Festival_Hall_of_Thutmose_III', 'https://en.wikipedia.org/wiki/Temple_of_Thutmose_III', 'fields-wd1-2026-09-26b-s003-rollback:3f793103-342f-40ca-a0fa-96b1065ad986:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Temple_of_Thutmose_III'' restored on Temple of Thutmose III', '[{"source": "https://en.wikipedia.org/wiki/Festival_Hall_of_Thutmose_III", "url": "https://en.wikipedia.org/wiki/Festival_Hall_of_Thutmose_III", "quote": "The Festival Hall of Thutmose III (Akh-menu) is an ancient shrine in Luxor (Thebes), Egypt. It is located at the heart of the Precinct of Amun-Re, in the Karnak Temple Complex.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/akhmenu/", "url": "https://digitalkarnak.ucsc.edu/akhmenu/", "quote": "Thutmose III began construction on the Akhmenu in the 23rd year of his reign and it was completed 7 years later.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL redirects to the Mortuary Temple of Thutmose III at Deir el-Bahari on the west bank, another site; this site is Thutmose III''s temple at Karnak, the Akh-menu (Wikidata Q13218743), whose English Wikipedia article is ''Festival Hall of Thutmose III'', and UCSC''s Digital Karnak describes the same Akhmenu built by Thutmose III.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Festival Hall of Thutmose III", "unreadable": false, "wikibase_item": "Q13218743"}}]'::jsonb),
    ('3f7e973f-f972-4677-9d02-6ae0b6942fcd'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:3f7e973f-f972-4677-9d02-6ae0b6942fcd:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Plain of Jars Site 3', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('3f7e973f-f972-4677-9d02-6ae0b6942fcd'::uuid, 'period_start', NULL, '-1240', 'fields-wd1-2026-09-26b-s003-rollback:3f7e973f-f972-4677-9d02-6ae0b6942fcd:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1240'' restored on Plain of Jars Site 3', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0091)", "decision": "clear", "status": "MISSING", "reasoning": "The stored -1240 is the OSL date for the emplacement of the jars at Site 2 (PLOS ONE 2021: 1240 BC to 660 BC, from sediments under jars at Site 2); no source dates Site 3 (Hai Hin Lat Khai) itself - the Plain of Jars Archaeological Project''s Site 3 page describes its groups and quarry without a date - so the field is emptied rather than borrowing another site''s date.", "value_page": null}]'::jsonb),
    ('3f9bdb7e-9739-47db-b323-1935cf6ea8d6'::uuid, 'site_type', 'City', 'Museum', 'fields-wd1-2026-09-26b-s003-rollback:3f9bdb7e-9739-47db-b323-1935cf6ea8d6:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Museum'' restored on Museo Archeologico Nazionale e Zona Archeologica di Luni', '[{"source": "https://en.wikipedia.org/wiki/Luni,_Italy", "url": "https://en.wikipedia.org/wiki/Luni,_Italy", "quote": "The Roman city was established in 177 BC by Publius Aelius, Marcus Aemilius Lepidus, and Gnaeus Sicinius", "outcome": "found"}, {"source": "https://vici.org/vici/17447/", "url": "https://vici.org/vici/17447/", "quote": "Class: City", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "CONFLICT", "reasoning": "The entry is the archaeological zone of ancient Luna together with the national museum built inside the excavations to show its finds; the sources describe the site itself as the Roman city (colony) of Luna - Wikipedia ''The Roman city was established in 177 BC'', Vici.org class City - so City is the most specific type for the ancient site, the museum being only its modern display.", "value_page": null}]'::jsonb),
    ('3f9bdb7e-9739-47db-b323-1935cf6ea8d6'::uuid, 'source_url', 'https://it.wikipedia.org/wiki/Luna_(colonia_romana)', 'https://en.wikipedia.org/wiki/Luni', 'fields-wd1-2026-09-26b-s003-rollback:3f9bdb7e-9739-47db-b323-1935cf6ea8d6:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Luni'' restored on Museo Archeologico Nazionale e Zona Archeologica di Luni', '[{"source": "https://it.wikipedia.org/wiki/Luna_(colonia_romana)", "url": "https://it.wikipedia.org/wiki/Luna_(colonia_romana)", "quote": "I resti della colonia di Luna si trovano nell''odierna frazione di Luni Scavi nel territorio del comune di Luni", "outcome": "found"}, {"source": "https://luni.cultura.gov.it/lantica-citta-di-luna", "url": "https://luni.cultura.gov.it/lantica-citta-di-luna", "quote": "nel 177 a.C. duemila cittadini romani partecipano alla fondazione della colonia di Luna", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English ''Luni'' is a disambiguation page and the English ''Luna (Etruria)'' only redirects to the modern comune; the Italian article ''Luna (colonia romana)'' is about the ancient city whose remains form the Zona Archeologica di Luni and names their location at Luni Scavi, and the Ministry of Culture''s museum site describes the same colony.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Luna (colonia romana)", "unreadable": false, "wikibase_item": "Q579763"}}]'::jsonb),
    ('403e3c53-6a70-49cc-81b8-2014542e53d3'::uuid, 'site_type', 'Stadium', 'Megalithic structures', 'fields-wd1-2026-09-26b-s003-rollback:403e3c53-6a70-49cc-81b8-2014542e53d3:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic structures'' restored on Stadium at Olympia', '[{"source": "https://en.wikipedia.org/wiki/Stadium_at_Olympia", "url": "https://en.wikipedia.org/wiki/Stadium_at_Olympia", "quote": "The Stadium at Olympia (also called the Olympia Stadium or the Olympia Stadion) is an ancient stadium at the archaeological site of Olympia, Greece, located to the east of the sanctuary of Zeus.", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=501", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=501", "quote": "The stadium of Olympia, situated east of the sacred Altis enclosure, was where the ancient Olympic Games and the Heraia, the women''s games in honour of Hera, were held.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Ministry of Culture both describe the site as the ancient stadium of Olympia where the Olympic Games were run, a 212 m racetrack with earthen spectator banks; the canonical type is Stadium, not megalithic structures.", "value_page": null}]'::jsonb),
    ('4054acf6-3542-4023-846b-bc13d419d79b'::uuid, 'source_url', 'https://uk.wikipedia.org/wiki/%D0%91%D0%BE%D1%80%D0%B8%D1%81%D1%84%D0%B5%D0%BD_(%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D1%96%D1%8F)', 'https://en.wikipedia.org/wiki/Berezan_Island', 'fields-wd1-2026-09-26b-s003-rollback:4054acf6-3542-4023-846b-bc13d419d79b:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Berezan_Island'' restored on Berezan Island', '[{"source": "https://uk.wikipedia.org/wiki/%D0%91%D0%BE%D1%80%D0%B8%D1%81%D1%84%D0%B5%D0%BD_(%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D1%96%D1%8F)", "url": "https://uk.wikipedia.org/wiki/%D0%91%D0%BE%D1%80%D0%B8%D1%81%D1%84%D0%B5%D0%BD_(%D0%BA%D0%BE%D0%BB%D0%BE%D0%BD%D1%96%D1%8F)", "quote": "Березанське поселення — найдавніша грецька колонія в Північному Причорномор''ї", "outcome": "found"}, {"source": "https://books.openedition.org/pccj/491", "url": "https://books.openedition.org/pccj/491", "quote": "The ancient settlement on the Berezan Island, which formerly was the peninsula, where the ancient Greeks first settled", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English article is about the island; the Ukrainian Wikipedia has an article on the site itself, the colony Borysthenes (the Berezan settlement), which Solovyov''s chapter describes as the same ancient settlement on Berezan Island.", "value_page": {"lang": "uk", "problem": null, "resolved_title": "Борисфен (колонія)", "unreadable": false, "wikibase_item": "Q11214098"}}]'::jsonb),
    ('40903f93-9088-4673-be0d-65d9e5583655'::uuid, 'site_type', 'Fortress', 'Temple complex', 'fields-wd1-2026-09-26b-s003-rollback:40903f93-9088-4673-be0d-65d9e5583655:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Temple complex'' restored on Cerro Quiac', '[{"source": "https://en.wikipedia.org/wiki/Cerro_Quiac", "url": "https://en.wikipedia.org/wiki/Cerro_Quiac", "quote": "An ethnohistoric document from the early Colonial period describes the site as a fortress founded by the Mam Maya, who were subsequently driven from the area by Kʼicheʼ expansion.", "outcome": "found"}, {"source": "https://www.soy502.com/articulo/cerro-quiac-historia-senderismo-cantel-quetzaltenango-102082", "url": "https://www.soy502.com/articulo/cerro-quiac-historia-senderismo-cantel-quetzaltenango-102082", "quote": "Se cree que fue originalmente una fortaleza de los mayas mames, quienes habitaron la región antes de la expansión del pueblo quiché, que posteriormente tomó control del lugar.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Soy502 both describe Cerro Quiac as a hilltop fortress (fortaleza) founded by the Mam Maya; its remains are two small groups of terraces and mounds with a single small temple, so Fortress fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('40fc1723-7365-4fcc-aab8-46f47e4eff17'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:40fc1723-7365-4fcc-aab8-46f47e4eff17:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Devil''s Causeway', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('40fc1723-7365-4fcc-aab8-46f47e4eff17'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:40fc1723-7365-4fcc-aab8-46f47e4eff17:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Devil''s Causeway', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and its copies say only that the road is thought to pre-date Hadrian''s Wall, and Keys to the Past gives just the broad ''Roman (43 to 410)'' period. Only the Bernician Studies Group''s PDF review estimates the date (mid-first to early second century), and no second independent source dates the road''s construction with a year or century.", "value_page": null}]'::jsonb),
    ('411cacb0-6312-4465-81f2-76417d209c17'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:411cacb0-6312-4465-81f2-76417d209c17:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Kit Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('411cacb0-6312-4465-81f2-76417d209c17'::uuid, 'period_start', '-3000', '-4500', 'fields-wd1-2026-09-26b-s003-rollback:411cacb0-6312-4465-81f2-76417d209c17:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4500'' restored on Kit Hill', '[{"source": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "url": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "quote": "Prehistoric people left their mark with a Neolithic long barrow (approx. 3000 BC) on the lower eastern slope and Bronze Age round barrows (2000-1500BC), forming part of a line of barrows along the Hingston Down.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=13257", "url": "https://www.megalithic.co.uk/article.php?sid=13257", "quote": "Kit Hill features a Neolithic Long Barrow dating back to about 3,000BC on its lower eastern slope, along with several Bronze Age barrows.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "MISSING", "reasoning": "Cornwall Council and the Megalithic Portal both date the earliest monument on Kit Hill, a Neolithic long barrow, to about 3000 BC, followed by Bronze Age round barrows; that start lies in the 3000 - 1500 BC bucket, not the stored 4500 - 3000 BC one.", "value_page": null}]'::jsonb),
    ('411cacb0-6312-4465-81f2-76417d209c17'::uuid, 'site_type', 'Barrow', 'Fortification', 'fields-wd1-2026-09-26b-s003-rollback:411cacb0-6312-4465-81f2-76417d209c17:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortification'' restored on Kit Hill', '[{"source": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "url": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "quote": "Prehistoric people left their mark with a Neolithic long barrow (approx. 3000 BC) on the lower eastern slope and Bronze Age round barrows (2000-1500BC), forming part of a line of barrows along the Hingston Down.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=61289", "url": "https://www.megalithic.co.uk/article.php?sid=61289", "quote": "The Cornwall HER lists 8 Barrows in a cemetery here.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient remains on Kit Hill are a Neolithic long barrow and a cemetery of Bronze Age round barrows (Cornwall Council, Megalithic Portal); the summit ''fort'' is an 18th-century folly imitating a Saxon fort (Cornwall Council) or a Civil War redoubt (Wikipedia), not an ancient fortification, so the type is Barrow.", "value_page": null}]'::jsonb),
    ('411cacb0-6312-4465-81f2-76417d209c17'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=61289', 'https://en.wikipedia.org/wiki/Kit_Hill', 'fields-wd1-2026-09-26b-s003-rollback:411cacb0-6312-4465-81f2-76417d209c17:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Kit_Hill'' restored on Kit Hill', '[{"source": "https://www.megalithic.co.uk/article.php?sid=61289", "url": "https://www.megalithic.co.uk/article.php?sid=61289", "quote": "Site Name: Kit Hill Tumuli", "outcome": "found"}, {"source": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "url": "https://www.cornwall.gov.uk/parks-leisure-and-culture/parks-and-open-spaces/country-parks/kit-hill-country-park/", "quote": "As the highest and most distinctive hill in the vicinity, Kit Hill may have had a religious significance in prehistoric times.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikipedia article is about the hill and country park, mostly its mining history; the Megalithic Portal''s Kit Hill Tumuli page is about the prehistoric barrow cemetery on the summit that makes this an ancient site, which Cornwall Council''s page also describes.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4154478d-f0ff-4f48-b577-48a8f647595c'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:4154478d-f0ff-4f48-b577-48a8f647595c:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Breidden Hill', '[{"source": "https://coflein.gov.uk/en/sites/141162", "url": "https://coflein.gov.uk/en/sites/141162", "quote": "The Breiddin Hillfort (the spelling preferred in archaeological literature) enclosure is formed on the summit of an isolated and abrupt north-east to south-west orientated ridge", "outcome": "found"}, {"source": "https://powysheritage.org/sites/the-breiddin/", "url": "https://powysheritage.org/sites/the-breiddin/", "quote": "the hill was being quarried for hard igneous rock, the quarry was advancing into the fort, and the archaeology was being removed a face at a time.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "RCAHMW''s Coflein record describes the site as the Breiddin Hillfort and Powys Heritage calls it the fort; a hillfort is a fort, not a fortress or citadel, so Fort is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('4154478d-f0ff-4f48-b577-48a8f647595c'::uuid, 'source_url', 'https://cy.wikipedia.org/wiki/Bryngaer_Breiddin', 'https://en.wikipedia.org/wiki/Breidden_Hill', 'fields-wd1-2026-09-26b-s003-rollback:4154478d-f0ff-4f48-b577-48a8f647595c:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Breidden_Hill'' restored on Breidden Hill', '[{"source": "https://cy.wikipedia.org/wiki/Bryngaer_Breiddin", "url": "https://cy.wikipedia.org/wiki/Bryngaer_Breiddin", "quote": "Gelwir hi weithiau wrth yr enw Caer Freiddin hefyd a Caer Breiddin.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/141162", "url": "https://coflein.gov.uk/en/sites/141162", "quote": "Breiddin Hillfort;Breidden Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about Breidden Hill, the hill the fort stands on; the hillfort''s own Wikipedia article is the Welsh ''Bryngaer Breiddin'', which Coflein''s record for the Breiddin Hillfort confirms is the same site.", "value_page": {"lang": "cy", "problem": null, "resolved_title": "Bryngaer Breiddin", "unreadable": false, "wikibase_item": "Q27535093"}}]'::jsonb),
    ('41552c37-9349-4c1d-a6e6-a7493f8b16bf'::uuid, 'period_name', '1 - 500 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:41552c37-9349-4c1d-a6e6-a7493f8b16bf:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Watling Street', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(43) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('41552c37-9349-4c1d-a6e6-a7493f8b16bf'::uuid, 'period_start', '43', '-3000', 'fields-wd1-2026-09-26b-s003-rollback:41552c37-9349-4c1d-a6e6-a7493f8b16bf:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Watling Street', '[{"source": "https://www.rpsgroup.com/about-us/news/roman-road-unearthed-beneath-old-kent-road-london/", "url": "https://www.rpsgroup.com/about-us/news/roman-road-unearthed-beneath-old-kent-road-london/", "quote": "Known as Watling Street, the road was built shortly after the Roman invasion of Britain in AD 43 nearly 2000 years ago.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Watling_Street", "url": "https://en.wikipedia.org/wiki/Watling_Street", "quote": "The Romans began constructing paved roads shortly after their invasion in AD 43. The London portion of Watling Street was rediscovered during Christopher Wren''s rebuilding of St Mary-le-Bow in 1671–73, following the Great Fire. Modern excavations date its construction to the winter from AD 47 to 48.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "MISSING", "reasoning": "RPS (reporting MOLA''s Old Kent Road excavation) and Wikipedia both date the road''s construction to shortly after the Roman invasion of AD 43, with the London section excavated to AD 47-48; earlier use by the Britons is undated. The attested start is therefore AD 43, in the 1 - 500 AD bucket, not 3000 BC.", "value_page": null}]'::jsonb),
    ('41aca9cf-1bfc-4ef6-90e2-3de22ff55604'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:41aca9cf-1bfc-4ef6-90e2-3de22ff55604:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Oddendale Stone Circle', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('41aca9cf-1bfc-4ef6-90e2-3de22ff55604'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s003-rollback:41aca9cf-1bfc-4ef6-90e2-3de22ff55604:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Oddendale Stone Circle', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "clear", "status": "MISSING", "reasoning": "The dates quoted for ''Oddendale'' (timber rings c. 2872-2350 BC, Turnbull and Walsh 1997) belong to the multi-phase ring cairn and timber circle excavated before quarrying at NY590137, about 0.8 km north (Megalithic Portal ''Hardendale Timber Circle''), not to the surviving concentric stone circle; sources for the stone circle itself only call it Neolithic or Neolithic and Bronze Age without a year, century or millennium, so the start is not attested.", "value_page": null}]'::jsonb),
    ('41aca9cf-1bfc-4ef6-90e2-3de22ff55604'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=329', 'https://en.wikipedia.org/wiki/Oddendale', 'fields-wd1-2026-09-26b-s003-rollback:41aca9cf-1bfc-4ef6-90e2-3de22ff55604:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Oddendale'' restored on Oddendale Stone Circle', '[{"source": "https://www.megalithic.co.uk/article.php?sid=329", "url": "https://www.megalithic.co.uk/article.php?sid=329", "quote": "Site Name: Oddendale", "outcome": "found"}, {"source": "https://wikishire.co.uk/wiki/Oddendale_Stone_Circle", "url": "https://wikishire.co.uk/wiki/Oddendale_Stone_Circle", "quote": "The Oddendale Stone Circle stands on the moorland above the little hamlet of Oddendale in the heart of Westmorland, east of Shap.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hamlet of Oddendale; the stone circle has no Wikipedia article and its Historic England list entry cannot be fetched by the checker, so the Megalithic Portal entry for the Oddendale stone circle is the page about this site; Wikishire names the same circle.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4200b0d7-2aae-4e07-acf3-a342b0c468ac'::uuid, 'site_type', 'Dolmen', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s003-rollback:4200b0d7-2aae-4e07-acf3-a342b0c468ac:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Necropolis/tombs complex'' restored on Dolmen de Lácara', '[{"source": "https://www.rutasconhistoria.es/loc/dolmen-de-lacara", "url": "https://www.rutasconhistoria.es/loc/dolmen-de-lacara", "quote": "El dolmen de Lácara es un monumento megalítico tipo sepulcro de corredor", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dolmen_del_prado_de_L%C3%A1cara", "url": "https://en.wikipedia.org/wiki/Dolmen_del_prado_de_L%C3%A1cara", "quote": "The one in Lácara is a dolmen of the most common type in the Extremaduran community, as it is a tomb with a long and well-developed corridor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe a single megalithic passage-grave dolmen, not a necropolis or complex of tombs; Dolmen is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('4235fa73-a58f-400b-a1f6-4998a8d2893f'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4235fa73-a58f-400b-a1f6-4998a8d2893f:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''< 4500 BC'' restored on Gärde', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4235fa73-a58f-400b-a1f6-4998a8d2893f'::uuid, 'period_start', NULL, '-5000', 'fields-wd1-2026-09-26b-s003-rollback:4235fa73-a58f-400b-a1f6-4998a8d2893f:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-5000'' restored on Gärde', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0023)", "decision": "clear", "status": "MISSING", "reasoning": "Every readable source (Krokom municipality, Offerdal and Tangeraasen village pages, Swedish, German and English Wikipedia, tourism guides) dates the Gärde carvings only as ''about 7000 years ago'' or ''up to 7000 years old'', and Swedish Wikipedia says they ''kan vara 7.000 år gamla'' (may be); none gives a calendar year, century or millennium BC, and a year worked out from an age in years is not accepted, so no two independent sources date the start and the field is cleared.", "value_page": null}]'::jsonb),
    ('4235fa73-a58f-400b-a1f6-4998a8d2893f'::uuid, 'source_url', 'https://fi.wikipedia.org/wiki/G%C3%A4rdenin_kalliopiirrokset', 'https://en.wikipedia.org/wiki/G%C3%A4rde', 'fields-wd1-2026-09-26b-s003-rollback:4235fa73-a58f-400b-a1f6-4998a8d2893f:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/G%C3%A4rde'' restored on Gärde', '[{"source": "https://fi.wikipedia.org/wiki/G%C3%A4rdenin_kalliopiirrokset", "url": "https://fi.wikipedia.org/wiki/G%C3%A4rdenin_kalliopiirrokset", "quote": "Gärdenin kalliopiirrokset sijaitsevat pienellä kalliolla Gärdesjönin laskujoen Gärdekoskessa", "outcome": "found"}, {"source": "https://uddautflykter.se/guide/jamtland/krokom/garde-hallristningar/", "url": "https://uddautflykter.se/guide/jamtland/krokom/garde-hallristningar/", "quote": "Gärde hällristningar, eller konsten att smyga på en älg, skapades för omkring 7000 år sedan av ett jägarfolk", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0137)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the village of Gärde; the carvings'' own Wikidata item (Q29380562, Petroglyphs of Gärde, RAÄ Offerdal 1:1) links to the Finnish Wikipedia article Gärdenin kalliopiirrokset, which is about this very site.", "value_page": {"lang": "fi", "problem": null, "resolved_title": "Gärdenin kalliopiirrokset", "unreadable": false, "wikibase_item": "Q29380562"}}]'::jsonb),
    ('43bb69c7-5c0e-4b99-baed-f23b921b0ca4'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s003-rollback:43bb69c7-5c0e-4b99-baed-f23b921b0ca4:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''4500 - 3000 BC'' restored on Kilmashogue', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('43bb69c7-5c0e-4b99-baed-f23b921b0ca4'::uuid, 'period_start', '-2000', '-4000', 'fields-wd1-2026-09-26b-s003-rollback:43bb69c7-5c0e-4b99-baed-f23b921b0ca4:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-4000'' restored on Kilmashogue', '[{"source": "https://curiousireland.ie/kilmashogue-wedge-tomb-kilmashogue-co-dublin-c-2000-b-c/", "url": "https://curiousireland.ie/kilmashogue-wedge-tomb-kilmashogue-co-dublin-c-2000-b-c/", "quote": "The Kilmashogue Wedge Tomb dates to c.2000 BC and would have originally been much larger and covered by a cairn of stones.", "outcome": "found"}, {"source": "https://www.megalithicireland.com/Kilmashogue.htm", "url": "https://www.megalithicireland.com/Kilmashogue.htm", "quote": "which would have been a lot deeper when it was first constructed around 2000 B.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "MISSING", "reasoning": "Curious Ireland and megalithicireland.com both date the construction of the Kilmashogue wedge tomb to c. 2000 BC (the Dublin Mountains Partnership places wedge tombs generally at 2500-2000 BC); that lies in the 3000 - 1500 BC bucket, not the stored 4500 - 3000 BC one.", "value_page": null}]'::jsonb),
    ('43bb69c7-5c0e-4b99-baed-f23b921b0ca4'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s003-rollback:43bb69c7-5c0e-4b99-baed-f23b921b0ca4:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Necropolis/tombs complex'' restored on Kilmashogue', '[{"source": "https://www.dublinmountains.ie/archaeology/archaeology/kilmashogue/", "url": "https://www.dublinmountains.ie/archaeology/archaeology/kilmashogue/", "quote": "The megalithic tomb at Kilmashogue is a fine example of a wedge tomb.", "outcome": "found"}, {"source": "https://www.megalithicireland.com/Kilmashogue.htm", "url": "https://www.megalithicireland.com/Kilmashogue.htm", "quote": "The chambered cairn at Kilmashogue is known as a wedge tomb", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Dublin Mountains Partnership and megalithicireland.com describe the site as a single megalithic wedge tomb (later cists inserted into its cairn), so the specific type is Tomb rather than a necropolis/tombs complex, and certainly not the mountain Wikidata describes.", "value_page": null}]'::jsonb),
    ('43bb69c7-5c0e-4b99-baed-f23b921b0ca4'::uuid, 'source_url', 'https://www.dublinmountains.ie/archaeology/archaeology/kilmashogue/', 'https://en.wikipedia.org/wiki/Kilmashogue', 'fields-wd1-2026-09-26b-s003-rollback:43bb69c7-5c0e-4b99-baed-f23b921b0ca4:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Kilmashogue'' restored on Kilmashogue', '[{"source": "https://www.dublinmountains.ie/archaeology/archaeology/kilmashogue/", "url": "https://www.dublinmountains.ie/archaeology/archaeology/kilmashogue/", "quote": "The megalithic tomb at Kilmashogue is a fine example of a wedge tomb.", "outcome": "found"}, {"source": "https://www.megalithicireland.com/Kilmashogue.htm", "url": "https://www.megalithicireland.com/Kilmashogue.htm", "quote": "The chambered cairn at Kilmashogue is known as a wedge tomb", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about Kilmashogue mountain and there is no article of the wedge tomb''s own; the Dublin Mountains Partnership page ''Kilmashogue Wedge Tomb'' is about this very monument and loads as plain HTML, and megalithicireland.com names the same tomb independently.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('44cf60cc-9ced-49af-acc5-9922cc3d6f38'::uuid, 'site_type', 'Villa', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s003-rollback:44cf60cc-9ced-49af-acc5-9922cc3d6f38:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Residence/villa/farmhouse'' restored on St Laurence School - Roman Villa', '[{"source": "https://www.bradfordonavonmuseum.co.uk/archives/3686", "url": "https://www.bradfordonavonmuseum.co.uk/archives/3686", "quote": "A dry summer showed where the villa could lie, under the playing field of St Laurence School.", "outcome": "found"}, {"source": "https://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml", "url": "https://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml", "quote": "Those criss-crossing lines turned out to be the walls of two lavish, Roman villas dating from the end of the third century AD, and were lived in until the early fifth century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Bradford on Avon Museum and the BBC describe the site as a Roman villa complex of two villa buildings with mosaics and a bath house, so the specific type Villa replaces the combined Residence/villa/farmhouse.", "value_page": null}]'::jsonb),
    ('44cf60cc-9ced-49af-acc5-9922cc3d6f38'::uuid, 'source_url', 'https://www.bradfordonavonmuseum.co.uk/archives/3686', 'https://en.wikipedia.org/wiki/St_Laurence_School', 'fields-wd1-2026-09-26b-s003-rollback:44cf60cc-9ced-49af-acc5-9922cc3d6f38:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/St_Laurence_School'' restored on St Laurence School - Roman Villa', '[{"source": "https://www.bradfordonavonmuseum.co.uk/archives/3686", "url": "https://www.bradfordonavonmuseum.co.uk/archives/3686", "quote": "A dry summer showed where the villa could lie, under the playing field of St Laurence School.", "outcome": "found"}, {"source": "https://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml", "url": "https://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml", "quote": "The mosaic, villa walls and hypercaust system have been uncovered by pupils and archaeologists at St Laurence School in Bradford on Avon.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the secondary school, and the villa gets only a short section. The Bradford on Avon Museum page ''St Laurence School Roman Villa'' is about the villa itself; the Historic England entry would be the register page but the checker cannot read it.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('44d6f27b-3a9f-49d3-99fa-b1a65380776a'::uuid, 'geom', 'SRID=4326;POINT(129.212 35.838)', '0101000020E61000001C11DDC83F276040F2EA5AE308E54140', 'fields-wd1-2026-09-26b-s003-rollback:44d6f27b-3a9f-49d3-99fa-b1a65380776a:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E61000001C11DDC83F276040F2EA5AE308E54140'' restored on The Tumuli Park Belt', '[{"source": "https://en.wikipedia.org/wiki/Daereungwon", "url": "https://en.wikipedia.org/wiki/Daereungwon", "quote": "35.838°N 129.212°E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/4401153789", "url": "https://www.openstreetmap.org/node/4401153789", "quote": "35.8406868, 129.2078893", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=62903", "url": "https://www.megalithic.co.uk/article.php?sid=62903", "quote": "Latitude: 35.838540N Longitude: 129.210570E", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q66197435", "url": "https://www.wikidata.org/wiki/Q66197435", "quote": "35°50''6.000\"N, 129°13''8.040\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared with the other Gyeongju belts, 5.1 km south of this one. The Tumuli Park Belt is the Daereungwon tomb complex: Wikipedia gives 35.838 N, 129.212 E, the Megalithic Portal 140 m from it, the OpenStreetMap node of the Machong tomb in the Noseo-dong group 480 m from it, and the belt''s Wikidata item (component 976-003) 710 m from it.", "value_page": null}]'::jsonb),
