    ('44d6f27b-3a9f-49d3-99fa-b1a65380776a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Daereungwon', 'https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas', 'fields-wd1-2026-09-26b-s003-rollback:44d6f27b-3a9f-49d3-99fa-b1a65380776a:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas'' restored on The Tumuli Park Belt', '[{"source": "https://en.wikipedia.org/wiki/Daereungwon", "url": "https://en.wikipedia.org/wiki/Daereungwon", "quote": "Daereungwon is a popular tourist attraction.", "outcome": "found"}, {"source": "https://discoverrealkorea.com/daereungwon-tombs-guide/", "url": "https://discoverrealkorea.com/daereungwon-tombs-guide/", "quote": "The UNESCO World Heritage description places these tombs within the Tumuli Park Belt of the Gyeongju Historic Areas", "outcome": "found"}, {"source": "https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=33871", "url": "https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=33871", "quote": "Gyeongju Daereungwon Tomb Complex consists of five tombs, Ancient Tombs of Gyeongju Nodong-ri, Noseo-ri, Hwangnam-ri, Hwango-ri, and Inwang-ri.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the whole World Heritage property (Q495241). The Tumuli Park Belt is the Daereungwon tomb complex (the Nodong-dong, Noseo-dong and Hwangnam-dong tomb groups): the English Wikipedia article on Daereungwon is the page about this site, a Daereungwon guide places these tombs in the Tumuli Park Belt, and the Korea Tourism Organization page names the same complex.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Daereungwon", "unreadable": false, "wikibase_item": "Q17278215"}}]'::jsonb),
    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'geom', 'SRID=4326;POINT(-1.2117 54.22682)', '0101000020E610000047DEBD573370F3BF4C4F9C547C1E4B40', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E610000047DEBD573370F3BF4C4F9C547C1E4B40'' restored on Roulston Scar, Sutton Bank', '[{"source": "https://www.wikidata.org/wiki/Q17662109", "url": "https://www.wikidata.org/wiki/Q17662109", "quote": "54°13''36.55\"N, 1°12''42.12\"W", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5153", "url": "https://www.megalithic.co.uk/article.php?sid=5153", "quote": "Latitude: 54.227544N Longitude: 1.213069W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The hillfort occupies the Roulston Scar promontory south of Sutton Bank; Wikidata''s item for the scheduled promontory fort (NHLE 1015502) gives 54°13''36.55\"N 1°12''42.12\"W and the Megalithic Portal gives SE 514 816 (54.2275N 1.2131W), while the stored point is the Sutton Bank hill point about 1.2 km further north, so the point is replaced.", "value_page": null}]'::jsonb),
