    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'lon', '-1.2117', '-1.2148927142533397', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''-1.2148927142533397'' restored on Roulston Scar, Sutton Bank', '[{"source": "https://www.wikidata.org/wiki/Q17662109", "url": "https://www.wikidata.org/wiki/Q17662109", "quote": "54°13''36.55\"N, 1°12''42.12\"W", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5153", "url": "https://www.megalithic.co.uk/article.php?sid=5153", "quote": "Latitude: 54.227544N Longitude: 1.213069W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The hillfort occupies the Roulston Scar promontory south of Sutton Bank; Wikidata''s item for the scheduled promontory fort (NHLE 1015502) gives 54°13''36.55\"N 1°12''42.12\"W and the Megalithic Portal gives SE 514 816 (54.2275N 1.2131W), while the stored point is the Sutton Bank hill point about 1.2 km further north, so the point is replaced.", "value_page": null}]'::jsonb),
    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on Roulston Scar, Sutton Bank', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on Roulston Scar, Sutton Bank', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "clear", "status": "MISSING", "reasoning": "The popular date ''c. 400 BC'' was a provisional estimate after the 2001 survey; the 2013 Landscape Research Centre excavation radiocarbon-dated the rampart''s construction to the ninth century BC and read the c. 400-200 cal BC dates as a later refurbishment. Only that one readable report gives the earlier start, so no two independent sources agree on the start and the stored -500 is emptied.", "value_page": null}]'::jsonb),
    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Roulston Scar, Sutton Bank', '[{"source": "https://en.wikipedia.org/wiki/Sutton_Bank", "url": "https://en.wikipedia.org/wiki/Sutton_Bank", "quote": "Just to the south of Sutton Bank is Roulston Scar, a massive hillfort built in the Iron Age", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5153", "url": "https://www.megalithic.co.uk/article.php?sid=5153", "quote": "Roulston Scar Fort, dating from c.400BC, is one of the largest Iron Age hillforts ever found in Britain, with defences surrounding the entire promontory, enclosing 60 acres.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as a hillfort (promontory fort) whose ramparts enclose the Roulston Scar plateau, not a fortress or citadel, so the most specific canonical type is Fort.", "value_page": null}]'::jsonb),
    ('4505d766-7814-4693-9ca3-04d707883088'::uuid, 'source_url', 'http://www.landscaperesearchcentre.org/html/Roulston2013/RS_EXC.html', 'https://en.wikipedia.org/wiki/Sutton_Bank', 'fields-wd1-2026-09-26b-s003-rollback:4505d766-7814-4693-9ca3-04d707883088:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Sutton_Bank'' restored on Roulston Scar, Sutton Bank', '[{"source": "http://www.landscaperesearchcentre.org/html/Roulston2013/RS_EXC.html", "url": "http://www.landscaperesearchcentre.org/html/Roulston2013/RS_EXC.html", "quote": "Archaeological Excavations at Roulston Scar, 2013", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5153", "url": "https://www.megalithic.co.uk/article.php?sid=5153", "quote": "Roulston Scar Fort, dating from c.400BC, is one of the largest Iron Age hillforts ever found in Britain, with defences surrounding the entire promontory, enclosing 60 acres.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Sutton Bank article is about the hill and gives the hillfort one sentence (Roulston Scar only redirects there); the Landscape Research Centre''s excavation report is a readable scholarly page about the Roulston Scar hillfort itself, and the Megalithic Portal independently describes the same fort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('450b08c8-702f-496a-8ce0-3946c646e80a'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:450b08c8-702f-496a-8ce0-3946c646e80a:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Cividade de Âncora', '[{"source": "https://prehistoricportugal.com/cividade-de-afife-ancora/", "url": "https://prehistoricportugal.com/cividade-de-afife-ancora/", "quote": "This enormous settlement was abandoned for millennia", "outcome": "found"}, {"source": "https://altominho.pt/pt/visitar/o-que-ver/cividade-de-%C3%A2ncora-afife/", "url": "https://altominho.pt/pt/visitar/o-que-ver/cividade-de-%C3%A2ncora-afife/", "quote": "Construído inicialmente na fase mais recente da Idade do Ferro, este importante povoado castrejo foi novamente habitado no período romano", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a walled castro (hillfort village) of the Iron Age; Prehistoric Portugal calls it an enormous settlement and AltoMinho a castro settlement (povoado castrejo), so the fortified-settlement type Settlement fits better than the town category City/town/settlement.", "value_page": null}]'::jsonb),
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:454b824c-cc1a-4846-97d8-7c036712895b:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Y Garn Goch', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:454b824c-cc1a-4846-97d8-7c036712895b:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Y Garn Goch', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0156)", "decision": "clear", "status": "MISSING", "reasoning": "Coflein says only that a Late Bronze Age or Iron Age date is most likely for the main construction of the hillfort, and Cadw that the two hillforts probably date to the Iron Age (a period definition, c. 800 BC - AD 74); no excavation or radiocarbon date for the start of the hillfort is recorded, so no two independent sources date the start and the stored -1500 (the item''s, not the site''s, date) is emptied.", "value_page": null}]'::jsonb),
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:454b824c-cc1a-4846-97d8-7c036712895b:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Y Garn Goch', '[{"source": "https://coflein.gov.uk/en/site/100866/", "url": "https://coflein.gov.uk/en/site/100866/", "quote": "Y Gaer Fawr or Garn Goch hillfort is a very large stone-walled defended enclosure occupying a dramatic isolated ridge.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2757", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2757", "quote": "The monument comprising an extensive area of landscape encompassing the remains of two hillforts probably dating to the Iron Age period", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2757", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2757", "quote": "The smaller fort known as Y Gaer Fach is situated on a subsidiary summit a short distance to the east.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0156)", "decision": "replace", "status": "CONFLICT", "reasoning": "Coflein (RCAHMW, type of site HILLFORT) and Cadw''s scheduling record for Garn Goch Camps (CM037, site type Hillfort) describe the site as two hillforts, Y Gaer Fawr and Y Gaer Fach; a hillfort is a fort, not a fortress or citadel, and the machine''s hill/summit class is only the ground it stands on.", "value_page": null}]'::jsonb),
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'source_url', 'https://cy.wikipedia.org/wiki/Bryngaerau_Garn_Goch', 'https://en.wikipedia.org/wiki/Y_Garn_Goch', 'fields-wd1-2026-09-26b-s003-rollback:454b824c-cc1a-4846-97d8-7c036712895b:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Y_Garn_Goch'' restored on Y Garn Goch', '[{"source": "https://cy.wikipedia.org/wiki/Bryngaerau_Garn_Goch", "url": "https://cy.wikipedia.org/wiki/Bryngaerau_Garn_Goch", "quote": "Mae bryngaerau Garn Goch yn ddwy fryngaer Geltaidd sy''n perthyn i Oes yr Haearn", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/site/100866/", "url": "https://coflein.gov.uk/en/site/100866/", "quote": "Y Gaer Fawr or Garn Goch hillfort is a very large stone-walled defended enclosure occupying a dramatic isolated ridge.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0156)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the hill (its Wikidata item is a hill and summit); the Welsh Wikipedia article Bryngaerau Garn Goch is about the two Garn Goch hillforts themselves and Coflein''s record of the same hillfort names it too.", "value_page": {"lang": "cy", "problem": null, "resolved_title": "Bryngaerau Garn Goch", "unreadable": false, "wikibase_item": "Q120446076"}}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'geom', 'SRID=4326;POINT(24.958 35.2953)', '0101000020E61000000529EA4134023940E543A3D8A5A54140', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E61000000529EA4134023940E543A3D8A5A54140'' restored on Sklavokampos', '[{"source": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "url": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "quote": "35.295278; 24.957944", "outcome": "found"}, {"source": "https://topostext.org/place/353250XSkl", "url": "https://topostext.org/place/353250XSkl", "quote": "Latitude: 35.295200\n Longitude: 24.958000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Wikipedia article on the villa and ToposText (Minoan villa excavated E of Gonies) both place the villa at 35.2953, 24.958 on the Tylissos-Anogeia road; the stored point lies 4.6 km east near Tylissos, not at the site.", "value_page": null}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'lat', '35.2953', '35.29412372562346', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:lat', 'rollback of fields-wd1-2026-09-26b-s003: lat ''35.29412372562346'' restored on Sklavokampos', '[{"source": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "url": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "quote": "35.295278; 24.957944", "outcome": "found"}, {"source": "https://topostext.org/place/353250XSkl", "url": "https://topostext.org/place/353250XSkl", "quote": "Latitude: 35.295200\n Longitude: 24.958000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Wikipedia article on the villa and ToposText (Minoan villa excavated E of Gonies) both place the villa at 35.2953, 24.958 on the Tylissos-Anogeia road; the stored point lies 4.6 km east near Tylissos, not at the site.", "value_page": null}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'lon', '24.958', '25.008609885852838', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''25.008609885852838'' restored on Sklavokampos', '[{"source": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "url": "https://el.wikipedia.org/wiki/%CE%88%CF%80%CE%B1%CF%85%CE%BB%CE%B7_%CF%84%CE%BF%CF%85_%CE%A3%CE%BA%CE%BB%CE%B1%CE%B2%CF%8C%CE%BA%CE%B1%CE%BC%CF%80%CE%BF%CF%85", "quote": "35.295278; 24.957944", "outcome": "found"}, {"source": "https://topostext.org/place/353250XSkl", "url": "https://topostext.org/place/353250XSkl", "quote": "Latitude: 35.295200\n Longitude: 24.958000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Wikipedia article on the villa and ToposText (Minoan villa excavated E of Gonies) both place the villa at 35.2953, 24.958 on the Tylissos-Anogeia road; the stored point lies 4.6 km east near Tylissos, not at the site.", "value_page": null}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Sklavokampos', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'period_start', '-1500', '-2000', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-2000'' restored on Sklavokampos', '[{"source": "https://www.tylisos.gr/index.php?option=content&task=view&id=134", "url": "https://www.tylisos.gr/index.php?option=content&task=view&id=134", "quote": "Οι ανασκαφές του Σπύρου Μαρινάτου, που επακολούθησαν, έφεραν στο φως ένα μέγαρο της μινωικής εποχής χτισμένο γύρω στο 1500 π.Χ.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=11653", "url": "https://www.megalithic.co.uk/article.php?sid=11653", "quote": "Minoan village from 1500 BC.", "outcome": "found"}, {"source": "https://www.history-archaeology.uoc.gr/en/activities-and-research/excavations/sklavokambos/", "url": "https://www.history-archaeology.uoc.gr/en/activities-and-research/excavations/sklavokambos/", "quote": "The excavator identified a building with twenty (20) rooms, which he called a ‘megaron’ or ‘rural villa’, and dated it entirely to the Late Minoan I period (c. 1600-1450 BC), without any earlier building phases (fig. 2).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "MISSING", "reasoning": "The Tylisos municipal site says Marinatos'' excavation revealed a Minoan megaron built around 1500 BC and the Megalithic Portal dates the site from 1500 BC; the University of Crete places the building within Late Minoan I (c. 1600-1450 BC) without fixing its construction more closely. Nothing dates the site to 2000 BC, so the start becomes c. 1500 BC.", "value_page": null}]'::jsonb),
    ('45b4e76d-0430-4abe-acfd-af61e2938421'::uuid, 'site_type', 'Villa', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:45b4e76d-0430-4abe-acfd-af61e2938421:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Sklavokampos', '[{"source": "https://www.ime.gr/chronos/02/crete/en/habitance/sklavoka.html", "url": "https://www.ime.gr/chronos/02/crete/en/habitance/sklavoka.html", "quote": "The Sklavokampos Villa, the ruins of which were completely destroyed in World War II, was situated at the foot of a rocky hill a small distance from Tylissos.", "outcome": "found"}, {"source": "https://topostext.org/place/353250XSkl", "url": "https://topostext.org/place/353250XSkl", "quote": "Σκλαβόκαμπος - Sklavokambos, Minoan villa excavated E of Gonies, Iraklio, Crete", "outcome": "found"}, {"source": "http://www.minoancrete.com/sklavokambos.htm", "url": "http://www.minoancrete.com/sklavokambos.htm", "quote": "The Minoan villa of Sklavokambos was discovered in 1930 when the road to Anoyeia was being constructed.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Foundation of the Hellenic World, ToposText and Minoan Crete all describe the site as a single Minoan villa (a two-storey rural ''megaron'' of about 20 rooms), not a town; the specific canonical type is Villa.", "value_page": null}]'::jsonb),
    ('45c293d7-6d69-47e5-adec-68b8e1ce6ec0'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:45c293d7-6d69-47e5-adec-68b8e1ce6ec0:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Çatalat Viranşehir Antik Kent', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('45c293d7-6d69-47e5-adec-68b8e1ce6ec0'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s003-rollback:45c293d7-6d69-47e5-adec-68b8e1ce6ec0:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Çatalat Viranşehir Antik Kent', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "clear", "status": "MISSING", "reasoning": "The only dating of the Çatalat ruins is the Ministry of Culture and Tourism text (\"V. yüzyıl Roma döneminden kalma yapı kalıntıları\"). turkiyedegez.com and the social-media posts repeat that same text almost word for word (IV.-V. century, estimated), so there are not two independent sources for the start and the field is emptied.", "value_page": null}]'::jsonb),
    ('4641bd18-a6d7-4f26-b895-e67f50af8e53'::uuid, 'geom', 'SRID=4326;POINT(47.578031 30.894692)', '0101000020E6100000E7F8FE7B19C6474017E7FB460FE63E40', 'fields-wd1-2026-09-26b-s003-rollback:4641bd18-a6d7-4f26-b895-e67f50af8e53:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E6100000E7F8FE7B19C6474017E7FB460FE63E40'' restored on Charax Spasinu', '[{"source": "https://en.wikipedia.org/wiki/Charax_Spasinu", "url": "https://en.wikipedia.org/wiki/Charax_Spasinu", "quote": "30°53′41″N 47°34′41″E", "outcome": "found"}, {"source": "https://vici.org/vici/10947/", "url": "https://vici.org/vici/10947/", "quote": "30.895039,47.58242", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0080)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia places Charax Spasinu at 30°53′41″N 47°34′41″E and the Vici.org archaeological atlas places Naysan / Spasinou Charax at 30.895039, 47.58242, 0.4 km apart; the stored point lies about 3 km west of both, so it is replaced by the Wikipedia point.", "value_page": null}]'::jsonb),
    ('4641bd18-a6d7-4f26-b895-e67f50af8e53'::uuid, 'lat', '30.894692', '30.89867061281174', 'fields-wd1-2026-09-26b-s003-rollback:4641bd18-a6d7-4f26-b895-e67f50af8e53:lat', 'rollback of fields-wd1-2026-09-26b-s003: lat ''30.89867061281174'' restored on Charax Spasinu', '[{"source": "https://en.wikipedia.org/wiki/Charax_Spasinu", "url": "https://en.wikipedia.org/wiki/Charax_Spasinu", "quote": "30°53′41″N 47°34′41″E", "outcome": "found"}, {"source": "https://vici.org/vici/10947/", "url": "https://vici.org/vici/10947/", "quote": "30.895039,47.58242", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0080)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia places Charax Spasinu at 30°53′41″N 47°34′41″E and the Vici.org archaeological atlas places Naysan / Spasinou Charax at 30.895039, 47.58242, 0.4 km apart; the stored point lies about 3 km west of both, so it is replaced by the Wikipedia point.", "value_page": null}]'::jsonb),
    ('4641bd18-a6d7-4f26-b895-e67f50af8e53'::uuid, 'lon', '47.578031', '47.54765272092646', 'fields-wd1-2026-09-26b-s003-rollback:4641bd18-a6d7-4f26-b895-e67f50af8e53:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''47.54765272092646'' restored on Charax Spasinu', '[{"source": "https://en.wikipedia.org/wiki/Charax_Spasinu", "url": "https://en.wikipedia.org/wiki/Charax_Spasinu", "quote": "30°53′41″N 47°34′41″E", "outcome": "found"}, {"source": "https://vici.org/vici/10947/", "url": "https://vici.org/vici/10947/", "quote": "30.895039,47.58242", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0080)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia places Charax Spasinu at 30°53′41″N 47°34′41″E and the Vici.org archaeological atlas places Naysan / Spasinou Charax at 30.895039, 47.58242, 0.4 km apart; the stored point lies about 3 km west of both, so it is replaced by the Wikipedia point.", "value_page": null}]'::jsonb),
    ('4695356b-52be-4152-8707-b1db00ef4707'::uuid, 'site_type', 'Archaeological site', 'Megalithic structures', 'fields-wd1-2026-09-26b-s003-rollback:4695356b-52be-4152-8707-b1db00ef4707:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic structures'' restored on Palaestra at Delphi', '[{"source": "https://mygreecetours.org/gymnasium-of-delphi/", "url": "https://mygreecetours.org/gymnasium-of-delphi/", "quote": "The first stone buildings rose in the fourth century BC, and Roman engineers later added heated bathing chambers and reworked the pool, giving the site the mixed Greek-and-Roman character visible in its ruins.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Palaestra_at_Delphi", "url": "https://en.wikipedia.org/wiki/Palaestra_at_Delphi", "quote": "The palaestra at Delphi is part of a gymnasium at the sanctuary.", "outcome": "found"}, {"source": "https://delphi.culture.gr/gymnasium/", "url": "https://delphi.culture.gr/gymnasium/", "quote": "Building complex of the 4th century B.C. which comprised the xystos and the palaestra togethe with their annexes, such as the baths and restaurants.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "CONFLICT", "reasoning": "All sources describe the site as the palaestra (wrestling court with rooms) of the 4th-century BC gymnasium, a ruined athletic building complex; nothing is megalithic, and since the canonical list has no gymnasium or palaestra type (a bath, stadium or forum it is not), the generic Archaeological site is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('46958435-223f-4648-93cc-153479b9c41c'::uuid, 'source_url', 'https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=487', 'https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park', 'fields-wd1-2026-09-26b-s003-rollback:46958435-223f-4648-93cc-153479b9c41c:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park'' restored on Peterborough Petroglyphs', '[{"source": "https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=487", "url": "https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=487", "quote": "Located in Petroglyphs Provincial Park, Peterborough Petroglyphs National Historic Site of Canada is a broad shelf of exposed marble located in a woodland setting in Peterborough, Ontario.", "outcome": "found"}, {"source": "https://www.heritagetrust.on.ca/heritagematters/articles/archeological-treasure-in-a-provincial-park", "url": "https://www.heritagetrust.on.ca/heritagematters/articles/archeological-treasure-in-a-provincial-park", "quote": "The Peterborough petroglyphs are the largest known concentration of Aboriginal rock carvings in Canada", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the provincial park and the petroglyphs have no Wikipedia article of their own, so the Parks Canada Directory of Federal Heritage Designations entry for the Peterborough Petroglyphs National Historic Site, the register record of this very site, is the source; the Ontario Heritage Trust names the same site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4770146e-aaa9-49ca-a35e-76ec91b5ea94'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4770146e-aaa9-49ca-a35e-76ec91b5ea94:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Saqqara Necropolis', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3050) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4770146e-aaa9-49ca-a35e-76ec91b5ea94'::uuid, 'period_start', '-3050', '-3000', 'fields-wd1-2026-09-26b-s003-rollback:4770146e-aaa9-49ca-a35e-76ec91b5ea94:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Saqqara Necropolis', '[{"source": "https://egypttimetravel.com/necropolis-of-saqqara", "url": "https://egypttimetravel.com/necropolis-of-saqqara", "quote": "The first use of the area as a place to receive tombs and burials dates back to 3,050 B.C., already in the First Dynasty.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Hor-Aha", "url": "https://en.wikipedia.org/wiki/Hor-Aha", "quote": "Hor-Aha probably ascended the throne in the mid 31st century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "MISSING", "reasoning": "Saqqara''s first burials date to the First Dynasty: Egypt Time Travel dates the first tombs to 3,050 B.C., and Wikipedia''s Hor-Aha article says the oldest mastaba at Saqqara, tomb S3357, dates to the reign of Hor-Aha, who ascended the throne in the mid 31st century BC. The attested start c. 3050 BC lies in the 4500 - 3000 BC bucket, not that of the stored -3000.", "value_page": null}]'::jsonb),
    ('47c37ef9-98ee-41d8-879b-e78db06295da'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:47c37ef9-98ee-41d8-879b-e78db06295da:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Kition', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1300) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('47c37ef9-98ee-41d8-879b-e78db06295da'::uuid, 'period_start', '-1300', '-3000', 'fields-wd1-2026-09-26b-s003-rollback:47c37ef9-98ee-41d8-879b-e78db06295da:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Kition', '[{"source": "https://www.visitcyprus.com/discover-cyprus/culture/sites-and-monuments/kition-archaeological-site/", "url": "https://www.visitcyprus.com/discover-cyprus/culture/sites-and-monuments/kition-archaeological-site/", "quote": "The architectural ruins of the ancient city-kingdom of Kition provide the first clear evidence that the Mycenaean Achaeans arrived in Larnaka (Larnaca) in the 13th century BC and stayed until the end of the 11th century BC.", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/7A7351CF22898DFEC22571A4002CA21C?OpenDocument", "url": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/7A7351CF22898DFEC22571A4002CA21C?OpenDocument", "quote": "The earliest phases of human habitation and religious worship in Kition, are found at the site of Kathari. Five consecutive temples and workshops for the smelting of copper, have already been excavated and are dated from the end of the 13th to the end of the 11th century B.C.", "outcome": "found"}, {"source": "https://www.gpsmycity.com/attractions/ancient-archeological-site-of-kition-49852.html", "url": "https://www.gpsmycity.com/attractions/ancient-archeological-site-of-kition-49852.html", "quote": "Established in the late 13th century BC by Mycenaean Greeks and later revived by Phoenician settlers from Tyre", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Department of Antiquities places the earliest habitation of Kition at Kathari at the end of the 13th century BC, and Visit Cyprus and GPSmyCity date the city''s establishment by Mycenaean settlers to the (late) 13th century BC; the Princeton Encyclopedia mentions older Bronze Age tombs in the area but gives no dated occupation, Wikidata''s 450 BC is far too late and the stored 3000 BC is unattested, so the start becomes the 13th century BC, -1300, in the 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('47c3b2a4-e476-4d38-b390-280c136fd1c5'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:47c3b2a4-e476-4d38-b390-280c136fd1c5:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Xultun', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('47c3b2a4-e476-4d38-b390-280c136fd1c5'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:47c3b2a4-e476-4d38-b390-280c136fd1c5:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Xultun', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0077)", "decision": "clear", "status": "MISSING", "reasoning": "Excavation reports (Del Cid, XXVIII Simposio 2014) date Xultun''s first settlement to the Middle Preclassic without a year, while popular pages give the Classic 250–900 CE span; no two independent sources state a year or century for the start of occupation, so the field is emptied.", "value_page": null}]'::jsonb),
    ('47e69f36-27eb-4f43-be08-b99edb0a1b19'::uuid, 'period_name', '1500 - 500 BC', '1 - 500 AD', 'fields-wd1-2026-09-26b-s003-rollback:47e69f36-27eb-4f43-be08-b99edb0a1b19:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1 - 500 AD'' restored on Temple of Nabu', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-883) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('47e69f36-27eb-4f43-be08-b99edb0a1b19'::uuid, 'period_start', '-883', '1', 'fields-wd1-2026-09-26b-s003-rollback:47e69f36-27eb-4f43-be08-b99edb0a1b19:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Temple of Nabu', '[{"source": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "url": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "quote": "Quand Assurnasirpal II (883-859) fonda le temple de Nabu", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Nimrud", "url": "https://de.wikipedia.org/wiki/Nimrud", "quote": "In einer Inschriften bezeichnet sich Assurnasirpal II. (883–859", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0013)", "decision": "replace", "status": "MISSING", "reasoning": "The French Ministry of Culture''s Nimrud site says Ashurnasirpal II (883-859) founded the temple of Nabu (Ezida) on the Nimrud acropolis, and the German Wikipedia says an inscription calls Ashurnasirpal II (883-859 BC) its founder, although the excavated building is Adad-nirari III''s (810-783 BC); the start is thus in the 9th century BC (bucket 1500-500 BC), not 1-500 AD, and is set to the first year of the founder''s reign.", "value_page": null}]'::jsonb),
    ('47e69f36-27eb-4f43-be08-b99edb0a1b19'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26b-s003-rollback:47e69f36-27eb-4f43-be08-b99edb0a1b19:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Temple complex'' restored on Temple of Nabu', '[{"source": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "url": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "quote": "Quand Assurnasirpal II (883-859) fonda le temple de Nabu", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Nimrud", "url": "https://de.wikipedia.org/wiki/Nimrud", "quote": "Der Nabû-Tempel, oder der Ezide, befindet sich im Südosten der Akropolis von Nimrud", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0013)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources call the Nimrud building a temple: the Ministry of Culture''s page speaks of the founding of the temple of Nabu, and the German Wikipedia of the Nabu temple (Nabû-Tempel, Ezida) on the acropolis of Nimrud; no source describes a separate complex of several temples, so the type is Temple.", "value_page": null}]'::jsonb),
    ('47e69f36-27eb-4f43-be08-b99edb0a1b19'::uuid, 'source_url', 'https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu', 'https://en.wikipedia.org/wiki/Temple_of_Nabu', 'fields-wd1-2026-09-26b-s003-rollback:47e69f36-27eb-4f43-be08-b99edb0a1b19:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Temple_of_Nabu'' restored on Temple of Nabu', '[{"source": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "url": "https://archeologie.culture.gouv.fr/nimrud/fr/histoire-du-temple-de-nabu", "quote": "Quand Assurnasirpal II (883-859) fonda le temple de Nabu", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Nimrud", "url": "https://de.wikipedia.org/wiki/Nimrud", "quote": "Der Nabû-Tempel, oder der Ezide, befindet sich im Südosten der Akropolis von Nimrud", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0013)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia URL is a disambiguation page listing seven temples of Nabu; English Wikipedia has no article on the Nimrud temple, while the French Ministry of Culture''s page ''Histoire du temple de Nabu | Nimrud'' is about this very temple (the Ezida on the Nimrud acropolis), and the German Wikipedia independently places the Nabu temple on the acropolis of Nimrud.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('47eb07cd-5c1c-4c0e-88c0-484d3b3411a1'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:47eb07cd-5c1c-4c0e-88c0-484d3b3411a1:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on Hegra - Mada''in Salih', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('47eb07cd-5c1c-4c0e-88c0-484d3b3411a1'::uuid, 'period_start', '-2000', '-100', 'fields-wd1-2026-09-26b-s003-rollback:47eb07cd-5c1c-4c0e-88c0-484d3b3411a1:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-100'' restored on Hegra - Mada''in Salih', '[{"source": "https://archeologie.culture.gouv.fr/monde/en/hegra", "url": "https://archeologie.culture.gouv.fr/monde/en/hegra", "quote": "Period of occupation 2nd millennium BCE - contemporary period", "outcome": "found"}, {"source": "https://hegraconservation.com/the-history-of-hegra/", "url": "https://hegraconservation.com/the-history-of-hegra/", "quote": "Some cairn tombs, that is burials covered by a heap of earth or stones dating between the end of the 3rd and beginning of the 2nd millennium BC, are the first remains of human activities detected on the Hegra site", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "The French ministry of culture''s page on the French-Saudi Hegra project dates the site''s occupation from the 2nd millennium BCE. Hegra Conservation names Bronze Age cairn tombs of the late 3rd to early 2nd millennium BC as the first human remains on the site, before the pre-Nabataean and Nabataean town. The start is c. 2000 BC, in the 3000 - 1500 BC bucket, not the stored 500 BC - 1 AD.", "value_page": null}]'::jsonb),
    ('480b7897-a76a-406c-9991-7c1c8228f905'::uuid, 'geom', 'SRID=4326;POINT(22.296264 44.261868)', '0101000020E610000048E48B9999593640F9F1904905204640', 'fields-wd1-2026-09-26b-s003-rollback:480b7897-a76a-406c-9991-7c1c8228f905:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E610000048E48B9999593640F9F1904905204640'' restored on Vrelo Šarkamen', '[{"source": "https://www.wikidata.org/wiki/Q12760990", "url": "https://www.wikidata.org/wiki/Q12760990", "quote": "44°15''42.556\"N, 22°17''46.219\"E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/1363128004", "url": "https://www.openstreetmap.org/node/1363128004", "quote": "44.2619105, 22.2969997", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point, 44.25, 22.35, is the centroid of Šarkamen village. The Institute of Archaeology places the Roman site of Vrelo 4 km west of the village. Wikidata''s item for the Roman Imperial Palace (heritage register AN 150) gives 44.26182, 22.29617, and OpenStreetMap maps the palace (Царска палата Шаркамен) at 44.26191, 22.29700, 0.06 km apart, so the site point replaces the village point.", "value_page": null}]'::jsonb),
