    ('480b7897-a76a-406c-9991-7c1c8228f905'::uuid, 'site_type', 'Palace', 'Residence/villa/farmhouse', 'fields-wd1-2026-09-26b-s003-rollback:480b7897-a76a-406c-9991-7c1c8228f905:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Residence/villa/farmhouse'' restored on Vrelo Šarkamen', '[{"source": "https://kulturnonasledje.in.rs/wp/language/en/roman-imperial-palace-sarkamen/", "url": "https://kulturnonasledje.in.rs/wp/language/en/roman-imperial-palace-sarkamen/", "quote": "Roman Imperial Palace Sarkamen", "outcome": "found"}, {"source": "https://sr.wikipedia.org/wiki/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%D0%A8%D0%B0%D1%80%D0%BA%D0%B0%D0%BC%D0%B5%D0%BD", "url": "https://sr.wikipedia.org/wiki/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%D0%A8%D0%B0%D1%80%D0%BA%D0%B0%D0%BC%D0%B5%D0%BD", "quote": "Царска палата Шаркамен је касноантички резиденцијални меморијални комплекс", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Classical Antiquity Heritage of Serbia site calls Vrelo the Roman Imperial Palace Sarkamen. Serbian Wikipedia calls it the Imperial Palace Šarkamen, a late antique residential and memorial complex. It was the fortified imperial residence of the tetrarch Maximinus Daia, so Palace is more specific than a villa or farmhouse.", "value_page": null}]'::jsonb),
    ('480b7897-a76a-406c-9991-7c1c8228f905'::uuid, 'source_url', 'https://sr.wikipedia.org/wiki/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%D0%A8%D0%B0%D1%80%D0%BA%D0%B0%D0%BC%D0%B5%D0%BD', 'https://en.wikipedia.org/wiki/%C5%A0arkamen', 'fields-wd1-2026-09-26b-s003-rollback:480b7897-a76a-406c-9991-7c1c8228f905:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/%C5%A0arkamen'' restored on Vrelo Šarkamen', '[{"source": "https://sr.wikipedia.org/wiki/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%D0%A8%D0%B0%D1%80%D0%BA%D0%B0%D0%BC%D0%B5%D0%BD", "url": "https://sr.wikipedia.org/wiki/%D0%A6%D0%B0%D1%80%D1%81%D0%BA%D0%B0_%D0%BF%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%D0%A8%D0%B0%D1%80%D0%BA%D0%B0%D0%BC%D0%B5%D0%BD", "quote": "Царска палата Шаркамен је касноантички резиденцијални меморијални комплекс", "outcome": "found"}, {"source": "https://ai.ac.rs/en/vrelo-sarkamen-near-negotin/", "url": "https://ai.ac.rs/en/vrelo-sarkamen-near-negotin/", "quote": "The Roman site of Vrelo is located 4 km west of the village of Šarkamen, which is located about 20 km northwest of Negotin, in eastern Serbia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about Šarkamen village. English Wikipedia''s ''Vrelo Šarkamen'' only redirects to it. The site''s own article is Serbian Wikipedia''s ''Царска палата Шаркамен'' on the imperial palace at Vrelo. The Institute of Archaeology names the same Roman site of Vrelo near Šarkamen.", "value_page": {"lang": "sr", "problem": null, "resolved_title": "Царска палата Шаркамен", "unreadable": false, "wikibase_item": "Q12760990"}}]'::jsonb),
    ('480f44f7-ad94-4ea5-bad8-fde912fa692b'::uuid, 'period_name', '4500 - 3000 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s003-rollback:480f44f7-ad94-4ea5-bad8-fde912fa692b:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''< 4500 BC'' restored on Ekornavallen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3300) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('480f44f7-ad94-4ea5-bad8-fde912fa692b'::uuid, 'period_start', '-3300', '-5000', 'fields-wd1-2026-09-26b-s003-rollback:480f44f7-ad94-4ea5-bad8-fde912fa692b:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-5000'' restored on Ekornavallen', '[{"source": "https://www.vastsverige.com/en/falkoping/produkter/ekornavallen/", "url": "https://www.vastsverige.com/en/falkoping/produkter/ekornavallen/", "quote": "The oldest grave was built during the Neolithic Period, approximately 3300 BC, while the most recent ones date back to the so called Viking Age, ca 800-1050 AD.", "outcome": "found"}, {"source": "https://www.stewegee.se/ekornavallen-160715.html", "url": "https://www.stewegee.se/ekornavallen-160715.html", "quote": "Gånggrift 3350-3200 f.Kr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "The burial ground begins with its Neolithic passage graves: the West Sweden tourist board dates the oldest grave to about 3300 BC and stewegee.se dates the passage grave Girommen to 3350-3200 BC. The stored -5000 (before 4500 BC) is unsupported; the start lies in the 4500-3000 BC bucket.", "value_page": null}]'::jsonb),
    ('480f44f7-ad94-4ea5-bad8-fde912fa692b'::uuid, 'site_type', 'Burial', 'Cemetery', 'fields-wd1-2026-09-26b-s003-rollback:480f44f7-ad94-4ea5-bad8-fde912fa692b:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Cemetery'' restored on Ekornavallen', '[{"source": "https://en.wikipedia.org/wiki/Ekornavallen", "url": "https://en.wikipedia.org/wiki/Ekornavallen", "quote": "Ekornavallen is an ancient burial ground", "outcome": "found"}, {"source": "https://www.vastsverige.com/en/falkoping/produkter/ekornavallen/", "url": "https://www.vastsverige.com/en/falkoping/produkter/ekornavallen/", "quote": "This means that humans have used Ekornavallen as a burial ground for more than 4,000 years!", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the West Sweden tourist board both describe Ekornavallen as a burial ground with passage graves, cairns, stone settings and standing stones used from the Neolithic to the Iron Age; no source calls it a ''cemetery'', so the type that the sources'' own word holds is Burial.", "value_page": null}]'::jsonb),
    ('485c3c0c-31f0-45a7-a06b-797c4c021466'::uuid, 'site_type', 'Dolmen', 'Mound/tumulus', 'fields-wd1-2026-09-26b-s003-rollback:485c3c0c-31f0-45a7-a06b-797c4c021466:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Mound/tumulus'' restored on Dolmen de Menga', '[{"source": "https://www.andaluciainformacion.es/articulo/antequera/fijada-entre-el-3800-y-3600-ane-la-fecha-mas-verosimil-del-dolmen-de-menga/202303051237032489540.html", "url": "https://www.andaluciainformacion.es/articulo/antequera/fijada-entre-el-3800-y-3600-ane-la-fecha-mas-verosimil-del-dolmen-de-menga/202303051237032489540.html", "quote": "Los resultados de estos trabajos, así, reflejan que el dolmen de Menga fue construido entre los años 3.800 y 3.600 antes de nuestra era", "outcome": "found"}, {"source": "https://www.nature.com/articles/s41598-023-47423-y", "url": "https://www.nature.com/articles/s41598-023-47423-y", "quote": "The Menga dolmen (Antequera, Malaga, Spain), listed in UNESCO World Heritage since July 2016", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dolmen_of_Menga", "url": "https://en.wikipedia.org/wiki/Dolmen_of_Menga", "quote": "a long barrow form of dolmen", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe Menga as a megalithic dolmen whose chamber is covered by an earthen mound; the dolmen is the monument itself, so Dolmen is more specific than Mound/tumulus.", "value_page": null}]'::jsonb),
    ('48e08ccf-7661-47c1-9a0e-ff9e205530e0'::uuid, 'geom', 'SRID=4326;POINT(50.491583 26.22775)', '0101000020E61000009834EBD8873E4940D9FC9556122A3A40', 'fields-wd1-2026-09-26b-s003-rollback:48e08ccf-7661-47c1-9a0e-ff9e205530e0:geom', 'rollback of fields-wd1-2026-09-26b-s003: geom ''0101000020E61000009834EBD8873E4940D9FC9556122A3A40'' restored on Jannusan Burial Mound Field', '[{"source": "https://www.megalithic.co.uk/article.php?sid=23926", "url": "https://www.megalithic.co.uk/article.php?sid=23926", "quote": "Latitude: 26.227750N Longitude: 50.491583E", "outcome": "found"}, {"source": "https://medomed.org/featured_item/burial-ensembles-of-bahrain-dilmun-and-tylos-cultural-landscape-and-hamad-town-mound-field-bahrain/", "url": "https://medomed.org/featured_item/burial-ensembles-of-bahrain-dilmun-and-tylos-cultural-landscape-and-hamad-town-mound-field-bahrain/", "quote": "N26 13 39.90 E50 29 29.70", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared by four sites, about 7 km south of Jannusan; the Megalithic Portal and Med-O-Med both give the point of ''the burial mound field of Jannusan'' (26.22775, 50.491583, south of Jannusan village and north of the Budaiya Highway, as BACA describes it), each reproducing the component coordinates of Bahrain''s official UNESCO Tentative List submission ''Burial Ensembles of Dilmun and Tylos''.", "value_page": null}]'::jsonb),
