    ('48e08ccf-7661-47c1-9a0e-ff9e205530e0'::uuid, 'lon', '50.491583', '50.48852073177949', 'fields-wd1-2026-09-26b-s003-rollback:48e08ccf-7661-47c1-9a0e-ff9e205530e0:lon', 'rollback of fields-wd1-2026-09-26b-s003: lon ''50.48852073177949'' restored on Jannusan Burial Mound Field', '[{"source": "https://www.megalithic.co.uk/article.php?sid=23926", "url": "https://www.megalithic.co.uk/article.php?sid=23926", "quote": "Latitude: 26.227750N Longitude: 50.491583E", "outcome": "found"}, {"source": "https://medomed.org/featured_item/burial-ensembles-of-bahrain-dilmun-and-tylos-cultural-landscape-and-hamad-town-mound-field-bahrain/", "url": "https://medomed.org/featured_item/burial-ensembles-of-bahrain-dilmun-and-tylos-cultural-landscape-and-hamad-town-mound-field-bahrain/", "quote": "N26 13 39.90 E50 29 29.70", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared by four sites, about 7 km south of Jannusan; the Megalithic Portal and Med-O-Med both give the point of ''the burial mound field of Jannusan'' (26.22775, 50.491583, south of Jannusan village and north of the Budaiya Highway, as BACA describes it), each reproducing the component coordinates of Bahrain''s official UNESCO Tentative List submission ''Burial Ensembles of Dilmun and Tylos''.", "value_page": null}]'::jsonb),
    ('48e08ccf-7661-47c1-9a0e-ff9e205530e0'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:48e08ccf-7661-47c1-9a0e-ff9e205530e0:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Jannusan Burial Mound Field', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('48e08ccf-7661-47c1-9a0e-ff9e205530e0'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s003-rollback:48e08ccf-7661-47c1-9a0e-ff9e205530e0:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Jannusan Burial Mound Field', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The stored 3000 BC is unsupported: the Bahrain Authority for Culture and Antiquities says the Jannusan mounds rose over an Early Dilmun ground level (c. 2000 BCE) and were used as cemeteries only from the Late Dilmun period (children''s jar cemetery c. 600-500 BCE) and in the Tylos period; no second independent source dates the start of the site.", "value_page": null}]'::jsonb),
    ('49af6562-eae0-42b1-8a52-6d808ae415ea'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:49af6562-eae0-42b1-8a52-6d808ae415ea:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on The Sanctuary & Temple of Apollo Hylates', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('49af6562-eae0-42b1-8a52-6d808ae415ea'::uuid, 'period_start', '-800', '-500', 'fields-wd1-2026-09-26b-s003-rollback:49af6562-eae0-42b1-8a52-6d808ae415ea:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on The Sanctuary & Temple of Apollo Hylates', '[{"source": "https://www.visitcyprus.com/discover-cyprus/culture/sites-and-monuments/sanctuary-of-apollon-hylates/", "url": "https://www.visitcyprus.com/discover-cyprus/culture/sites-and-monuments/sanctuary-of-apollon-hylates/", "quote": "Apollon Hylates, God of the Woodland, was the protector of Kourion and it is believed that he was worshipped at the site from the 8th century BC to the 4th century AD.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=61506", "url": "https://www.megalithic.co.uk/article.php?sid=61506", "quote": "It was probably founded in the 8th century BCE, later it was rebuild in roman times.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Hylates", "url": "https://en.wikipedia.org/wiki/Hylates", "quote": "It seems that the worship of Apollo on this site began as early as the eighth century BC and continued until the fourth century AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "MISSING", "reasoning": "The Cyprus Tourism Organisation, the Megalithic Portal and English Wikipedia all date the start of worship at the sanctuary to the 8th century BC, which falls in 1500 - 500 BC rather than the stored 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
