    ('4a4dcea2-c940-416e-a217-b397396179e1'::uuid, 'period_start', NULL, '-5000', 'fields-wd1-2026-09-26b-s003-rollback:4a4dcea2-c940-416e-a217-b397396179e1:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-5000'' restored on Cefn Bryn', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "clear", "status": "MISSING", "reasoning": "Cefn Bryn holds Neolithic tombs and forty or more Bronze Age cairns; only Cadw dates the ridge-top cairns with years (probably Bronze Age, c. 2300 - 800 BC), the other pages repeat it or give no year, and nothing independent supports the stored start before 4500 BC (only possible Mesolithic flints under the Great Cairn), so no start can be sourced.", "value_page": null}]'::jsonb),
