    ('4a4e2c30-8a8f-4b7d-8e7c-c0e837b94760'::uuid, 'period_start', '1460', '1', 'fields-wd1-2026-09-26b-s003-rollback:4a4e2c30-8a8f-4b7d-8e7c-c0e837b94760:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1'' restored on Huánuco Pampa', '[{"source": "https://www.gochile.cl/en/huanuco-pampa-archaeological-complex/", "url": "https://www.gochile.cl/en/huanuco-pampa-archaeological-complex/", "quote": "Its construction began in 1460 and was interrupted in 1539 by the arrival and conquest of the Spaniards.", "outcome": "found"}, {"source": "https://www.explorandes.com/blog/huanuco-pampa", "url": "https://www.explorandes.com/blog/huanuco-pampa", "quote": "Huánuco Pampa was constructed during the height of Inca expansion in the 15th century", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "replace", "status": "MISSING", "reasoning": "Huánuco Pampa was an Inca foundation built under Túpac Yupanqui during the 15th-century expansion, its construction beginning c. 1460; this is in the 1000-1500 AD bucket, so the stored 1 AD is wrong and is replaced by 1460.", "value_page": null}]'::jsonb),
    ('4a4e2c30-8a8f-4b7d-8e7c-c0e837b94760'::uuid, 'site_type', 'City/town/settlement', 'Temple complex', 'fields-wd1-2026-09-26b-s003-rollback:4a4e2c30-8a8f-4b7d-8e7c-c0e837b94760:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Temple complex'' restored on Huánuco Pampa', '[{"source": "https://en.wikipedia.org/wiki/Hu%C3%A1nuco_Pampa", "url": "https://en.wikipedia.org/wiki/Hu%C3%A1nuco_Pampa", "quote": "The ruins of the city lie on a plateau above the Urqumayu or Vizcarra River in the central Andes", "outcome": "found"}, {"source": "https://www.gochile.cl/en/huanuco-pampa-archaeological-complex/", "url": "https://www.gochile.cl/en/huanuco-pampa-archaeological-complex/", "quote": "Also known as Huánuco Marka or Huánuco Viejo, it was an Inca administrative center and an important center for the production of high quality fabrics", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "replace", "status": "MISSING", "reasoning": "Huánuco Pampa was an Inca provincial administrative city of some 4,000 buildings with plaza, ushnu, residential quarters and storehouses, not primarily a temple complex; both sources describe it as a city and administrative center, so City/town/settlement replaces Temple complex.", "value_page": null}]'::jsonb),
