    ('4a87bc78-0813-4110-aa1e-3818326bee00'::uuid, 'site_type', 'Cave', 'Archaeological site', 'fields-wd1-2026-09-26b-s003-rollback:4a87bc78-0813-4110-aa1e-3818326bee00:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Archaeological site'' restored on Cave of the Guanches', '[{"source": "https://en.wikipedia.org/wiki/Cave_of_the_Guanches", "url": "https://en.wikipedia.org/wiki/Cave_of_the_Guanches", "quote": "The protected archaeological environment is in the municipality of Icod de los Vinos and revolves around the Cave of the Guanches.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=60125", "url": "https://www.megalithic.co.uk/article.php?sid=60125", "quote": "Important archaeological Guanches site. The cave was inhabited from the 6th century BCE.", "outcome": "found"}, {"source": "https://icoddelosvinos.es/patrimonio/cueva-de-los-guanches/", "url": "https://icoddelosvinos.es/patrimonio/cueva-de-los-guanches/", "quote": "Esta cueva se localiza en una zona elevada del acantilado de Playa Moreno, a unos 125 metros de altitud. La cueva es un tubo volcánico cuya boca está orientada al oeste", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal and the Icod town hall all describe the site as an inhabited cave (a lava tube) with its surrounding finds; the more specific canonical type than the generic Archaeological site is Cave.", "value_page": null}]'::jsonb),
