    ('4ab1bd6e-a7fd-41c3-b341-9959d77d5a6e'::uuid, 'period_start', '-2100', '-500', 'fields-wd1-2026-09-26b-s003-rollback:4ab1bd6e-a7fd-41c3-b341-9959d77d5a6e:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on Great Ziggurat of Ur', '[{"source": "https://en.wikipedia.org/wiki/Ziggurat_of_Ur", "url": "https://en.wikipedia.org/wiki/Ziggurat_of_Ur", "quote": "The structure was built during the Early Bronze Age (21st century BC) by King Ur-Nammu of the Third Dynasty of Ur", "outcome": "found"}, {"source": "https://artincontext.org/ziggurat-of-ur/", "url": "https://artincontext.org/ziggurat-of-ur/", "quote": "The Sumerian Ziggurat of Ur was built in the 21st century BCE in what is today the Dhi Qar Province in Iraq.", "outcome": "found"}, {"source": "https://www.worldhistory.org/Ziggurat_of_Ur/", "url": "https://www.worldhistory.org/Ziggurat_of_Ur/", "quote": "The ruins of the Great Ziggurat of Ur, built by the Sumerian king Ur-Nammu and his son Shulgi of Ur, c. 21st century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0080)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, Art in Context and World History Encyclopedia all date the construction of the ziggurat by Ur-Nammu to the 21st century BC (c. 2100 BC), in the 3000-1500 BC bucket; the stored 500 BC confuses it with the later Neo-Babylonian restoration by Nabonidus, so it is replaced.", "value_page": null}]'::jsonb),
