    ('4b0f332b-9289-4a80-9843-3df96b119343'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Yaxha', 'https://en.wikipedia.org/wiki/Cultural_Triangle_Yaxha-Nakum-Naranjo_National_Park', 'fields-wd1-2026-09-26b-s003-rollback:4b0f332b-9289-4a80-9843-3df96b119343:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Cultural_Triangle_Yaxha-Nakum-Naranjo_National_Park'' restored on Yaxhá', '[{"source": "https://en.wikipedia.org/wiki/Yaxha", "url": "https://en.wikipedia.org/wiki/Yaxha", "quote": "Yaxha (or Yaxhá in Spanish orthography) is a Mesoamerican archaeological site in the northeast of the Petén Basin in modern-day Guatemala.", "outcome": "found"}, {"source": "https://www.themayanruinswebsite.com/yaxha.html", "url": "https://www.themayanruinswebsite.com/yaxha.html", "quote": "Yaxha, Blue-Green Water in Maya, is a large, picturesque site located within the Yaxha-Nakum-Naranjo National Park", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is the Cultural Triangle Yaxha-Nakum-Naranjo National Park, the protected area; the Maya city has its own English Wikipedia article Yaxha (17.0775N 89.4025W), and a second independent page describes Yaxha as a large site located within that national park.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Yaxha", "unreadable": false, "wikibase_item": "Q1540906"}}]'::jsonb),
    ('4b34735f-5ab5-451a-8b4e-565828ceec86'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4b34735f-5ab5-451a-8b4e-565828ceec86:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''3000 - 1500 BC'' restored on Angkor Borei and Phnom Da', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4b34735f-5ab5-451a-8b4e-565828ceec86'::uuid, 'period_start', '-400', '-3000', 'fields-wd1-2026-09-26b-s003-rollback:4b34735f-5ab5-451a-8b4e-565828ceec86:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-3000'' restored on Angkor Borei and Phnom Da', '[{"source": "https://journals.lib.washington.edu/index.php/BIPPA/article/view/11998", "url": "https://journals.lib.washington.edu/index.php/BIPPA/article/view/11998", "quote": "Excavations at the ancient capital of Angkor Borei suggest a continuous occupation of the area from the 4th century BC onwards", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Angkor_Borei_and_Phnom_Da", "url": "https://en.wikipedia.org/wiki/Angkor_Borei_and_Phnom_Da", "quote": "Stephen A. Murphy takes the cemetery evidence to indicate settlement at Angkor Borei from about 500 BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator (Stark, Lower Mekong Archaeological Project) dates continuous occupation of Angkor Borei from the 4th century BC and Murphy from about 500 BCE; both fall in the 500 BC - 1 AD bucket, not the stored 3000 - 1500 BC one (the 1523 BC carbon date in Wikipedia is not borne out by the excavators).", "value_page": null}]'::jsonb),
    ('4b34735f-5ab5-451a-8b4e-565828ceec86'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s003-rollback:4b34735f-5ab5-451a-8b4e-565828ceec86:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Temple complex'' restored on Angkor Borei and Phnom Da', '[{"source": "https://beyondangkor.org/index.php/Angkor_Borei", "url": "https://beyondangkor.org/index.php/Angkor_Borei", "quote": "Angkor Borei is unusual in that it''s possibly the only ancient city site in Cambodia that is also a modern-day town.", "outcome": "found"}, {"source": "https://www.nature.com/articles/s41598-022-26799-3", "url": "https://www.nature.com/articles/s41598-022-26799-3", "quote": "The walled and moated Angkor Borei site was first occupied in the middle of the first millennium BCE and is one of the earliest dated urban sites in the Mekong Delta in either Cambodia or Vietnam", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "MISSING", "reasoning": "Angkor Borei is a walled and moated ancient city of about 300 ha, a Funan capital and one of the earliest urban sites of the Mekong Delta (Beyond Angkor, Scientific Reports); the Phnom Da temples are its hill sanctuary, so City describes the site better than Temple complex.", "value_page": null}]'::jsonb),
    ('4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Torre d''en Galmés', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1700) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127'::uuid, 'period_start', '-1700', '-1500', 'fields-wd1-2026-09-26b-s003-rollback:4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Torre d''en Galmés', '[{"source": "https://www.illesbalears.travel/en/menorca/archaeological-site-poblat-de-la-torre-den-galmes", "url": "https://www.illesbalears.travel/en/menorca/archaeological-site-poblat-de-la-torre-den-galmes", "quote": "The first human inhabitants date back to the Bronze Age (roughly 1700 BCE), and the site reflects the different phases of prehistory on Minorca practically until the Christian reconquest by King Alfonso III of Aragón in 1287, when it was finally abandoned for good.", "outcome": "found"}, {"source": "https://www.menorca.es/es/Poblado_talayotico_de_Torre_den_Galmes/8446", "url": "https://www.menorca.es/es/Poblado_talayotico_de_Torre_den_Galmes/8446", "quote": "Cronológicamente, perduró desde el periodo naviforme (1700-1400 a.C.), del cual se conserva un hipogeo cerca de la zona de recogida de agua, hasta la época romana tardía", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "replace", "status": "MISSING", "reasoning": "The Balearic tourism agency dates the first inhabitants of Torre d''en Galmés to roughly 1700 BCE and the Consell Insular de Menorca''s page to the Naviform period (1700-1400 BC), from which a hypogeum survives; the start therefore lies in the 3000 - 1500 BC bucket, not the stored 1500 - 500 BC one (1400 BC in Wikipedia is the start of the Talayotic town, not of the site''s occupation).", "value_page": null}]'::jsonb),
    ('4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127'::uuid, 'site_type', 'Village', 'City/town/settlement', 'fields-wd1-2026-09-26b-s003-rollback:4b5e5d49-dc89-4a64-9c7d-d2dc63aa7127:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''City/town/settlement'' restored on Torre d''en Galmés', '[{"source": "https://www.illesbalears.travel/en/menorca/archaeological-site-poblat-de-la-torre-den-galmes", "url": "https://www.illesbalears.travel/en/menorca/archaeological-site-poblat-de-la-torre-den-galmes", "quote": "The talayotic village of Torre d''en Galmés is located in the township of Alaior, and belongs to the Ministry of Culture, which acquired it in the early 1970s.", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Torre_d%27en_Galm%C3%A9s", "url": "https://es.wikipedia.org/wiki/Torre_d%27en_Galm%C3%A9s", "quote": "El poblado talayótico de Torre d''en Gaumés (o Galmés), situado en Menorca, es uno de los yacimientos arqueológicos más grandes de las Islas Baleares.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Balearic tourism agency calls Torre d''en Galmés a talayotic village and Spanish Wikipedia a poblado talayótico (talayotic village), matching its Wikidata class talaiotic village; Village is the most specific canonical type and more precise than the combined City/town/settlement.", "value_page": null}]'::jsonb),
    ('4bbe3ea8-22be-4609-bb4c-e5b13e3d4934'::uuid, 'period_name', '500 - 1000 AD', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s003-rollback:4bbe3ea8-22be-4609-bb4c-e5b13e3d4934:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1000 - 1500 AD'' restored on Ingapirca Archaeological Complex', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(500) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4bbe3ea8-22be-4609-bb4c-e5b13e3d4934'::uuid, 'period_start', '500', '1000', 'fields-wd1-2026-09-26b-s003-rollback:4bbe3ea8-22be-4609-bb4c-e5b13e3d4934:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''1000'' restored on Ingapirca Archaeological Complex', '[{"source": "https://www.gob.ec/inpc/tramites/solicitud-ingreso-museos-sitio-areas-arqueologica-complejo-arqueologico-ingapirca", "url": "https://www.gob.ec/inpc/tramites/solicitud-ingreso-museos-sitio-areas-arqueologica-complejo-arqueologico-ingapirca", "quote": "Concentra a la cultura cañari (500 d. C.), como zona ceremonial importante", "outcome": "found"}, {"source": "https://www.ingapircaecuador.com/en", "url": "https://www.ingapircaecuador.com/en", "quote": "500-1400 AD", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "MISSING", "reasoning": "Ecuador''s heritage institute (INPC, via gob.ec) dates the Cañari occupation of the Ingapirca complex to 500 AD, and the site guide''s timeline gives 500-1400 AD for the Cañari settlement and ceremonial centre (Pilaloma); the Inca buildings came only in the late 15th century, so the start lies in the 500-1000 AD bucket, not in 1000-1500 AD.", "value_page": null}]'::jsonb),
    ('4bbe3ea8-22be-4609-bb4c-e5b13e3d4934'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ingapirca', 'https://www.ecuadorhop.com/inca-ruins-ecuador/', 'fields-wd1-2026-09-26b-s003-rollback:4bbe3ea8-22be-4609-bb4c-e5b13e3d4934:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://www.ecuadorhop.com/inca-ruins-ecuador/'' restored on Ingapirca Archaeological Complex', '[{"source": "https://en.wikipedia.org/wiki/Ingapirca", "url": "https://en.wikipedia.org/wiki/Ingapirca", "quote": "became the first European to make a scientific description of Ingapirca, which he visited in 1739 in the course of his expedition to South America.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=24434", "url": "https://www.megalithic.co.uk/article.php?sid=24434", "quote": "Ingapirca is the largest Incan site in Ecuador.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored travel page redirects to another site; the English Wikipedia article Ingapirca (Wikidata Q1478056, archaeological site) is about the ruins and Temple of the Sun of this very complex, and the Megalithic Portal names the same site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Ingapirca", "unreadable": false, "wikibase_item": "Q1478056"}}]'::jsonb),
    ('4c05611f-65b3-4481-a43d-f64e839e0c48'::uuid, 'source_url', 'https://kulturenvanteri.com/en/yer/haron-kabartmasi/', 'https://www.google.com.au/maps/place/HARON+(CHARON%C4%B0ON)+KABARTMASI/@36.2093737,36.1784416,79m/data=!3m1!1e3!4m5!3m4!1s0x1525c169eef4ff21:0x9d37dbacf5ebcf2a!8m2!3d36.2092551!4d36.1788737', 'fields-wd1-2026-09-26b-s003-rollback:4c05611f-65b3-4481-a43d-f64e839e0c48:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://www.google.com.au/maps/place/HARON+(CHARON%C4%B0ON)+KABARTMASI/@36.2093737,36.1784416,79m/data=!3m1!1e3!4m5!3m4!1s0x1525c169eef4ff21:0x9d37dbacf5ebcf2a!8m2!3d36.2092551!4d36.1788737'' restored on Haron (Charonian) Kabartmasi', '[{"source": "https://kulturenvanteri.com/en/yer/haron-kabartmasi/", "url": "https://kulturenvanteri.com/en/yer/haron-kabartmasi/", "quote": "Also known as Cehennem Kayıkçısı Kabartması, Haron Büstü.", "outcome": "found"}, {"source": "https://tr.wikipedia.org/wiki/K%C3%BC%C3%A7%C3%BCkdalyan,_Antakya", "url": "https://tr.wikipedia.org/wiki/K%C3%BC%C3%A7%C3%BCkdalyan,_Antakya", "quote": "Haron (Charonion) Kabartması, Aziz Petrus Kilisesi''nin 200 m kuzeyinde bulunan kayalara oyulmuş dev bir büst.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0144)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Google Maps link is not a page about the site. The relief has no English Wikipedia article (the Dutch ''Charonion'' article never names it Haron), so the Kültür Envanteri inventory entry for the Haron Kabartması in Antakya is the source; Turkish Wikipedia''s Küçükdalyan article names the same relief 200 m north of St Peter''s church.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
