    ('4c05fdee-8903-43a8-ab47-0a6d688e04c1'::uuid, 'period_name', '4500 - 3000 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s003-rollback:4c05fdee-8903-43a8-ab47-0a6d688e04c1:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''500 BC - 1 AD'' restored on Nether Largie South Cairn, Kilmartin Glen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3700) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4c05fdee-8903-43a8-ab47-0a6d688e04c1'::uuid, 'period_start', '-3700', '-500', 'fields-wd1-2026-09-26b-s003-rollback:4c05fdee-8903-43a8-ab47-0a6d688e04c1:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-500'' restored on Nether Largie South Cairn, Kilmartin Glen', '[{"source": "https://www.kilmartin.org/self-guided-trail", "url": "https://www.kilmartin.org/self-guided-trail", "quote": "This is one of the oldest monuments in the glen built over 5,000 years ago (3700-3600BC) and originally it would have looked quite different to what you see before you today.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "It is a Neolithic chambered cairn of the Clyde type, probably dating from the fourth millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "MISSING", "reasoning": "Kilmartin Museum''s trail dates the building of Nether Largie South Cairn to 3700-3600 BC and Wikipedia to the fourth millennium BC; both put the start in the 4500-3000 BC bucket, not the stored 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('4c05fdee-8903-43a8-ab47-0a6d688e04c1'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Nether_Largie_South', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'fields-wd1-2026-09-26b-s003-rollback:4c05fdee-8903-43a8-ab47-0a6d688e04c1:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' restored on Nether Largie South Cairn, Kilmartin Glen', '[{"source": "https://de.wikipedia.org/wiki/Nether_Largie_South", "url": "https://de.wikipedia.org/wiki/Nether_Largie_South", "quote": "Nether Largie South ist eine Megalithanlage des Typs Clyde Tomb", "outcome": "found"}, {"source": "https://www.historicenvironment.scot/visit/all/kilmartin-glen-nether-largie-south-cairn/history-and-stories/", "url": "https://www.historicenvironment.scot/visit/all/kilmartin-glen-nether-largie-south-cairn/history-and-stories/", "quote": "Nether Largie South is the oldest of the five cairns that stretch along the valley floor.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the Kilmartin Glen area; the site itself is the Nether Largie South chambered cairn, which has its own German Wikipedia article (Wikidata Q1267317) and a Historic Environment Scotland visitor page describing it.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Nether Largie South", "unreadable": false, "wikibase_item": "Q1267317"}}]'::jsonb),
    ('4c555421-7d9c-4921-b5c1-f5e386c6f6bd'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4c555421-7d9c-4921-b5c1-f5e386c6f6bd:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Asklepion, Kos', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4c555421-7d9c-4921-b5c1-f5e386c6f6bd'::uuid, 'period_start', '-400', '-1500', 'fields-wd1-2026-09-26b-s003-rollback:4c555421-7d9c-4921-b5c1-f5e386c6f6bd:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Asklepion, Kos', '[{"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2395", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2395", "quote": "Chronology 4th century BC - 4th century AD", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Asklepieion_von_Kos", "url": "https://de.wikipedia.org/wiki/Asklepieion_von_Kos", "quote": "Auf der mittleren Ebene, dem ältesten Teil der Anlage, die bis in das 4. Jahrhundert v. Chr. zurückdatiert wird", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0062)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture dates the sanctuary of Asklepios at Kos from the 4th century BC, and German Wikipedia dates its oldest part, the middle terrace, to the 4th century BC; the start lies in 500 BC - 1 AD, not 1500 - 500 BC.", "value_page": null}]'::jsonb),
    ('4c555421-7d9c-4921-b5c1-f5e386c6f6bd'::uuid, 'site_type', 'Sanctuary', 'Megalithic stones', 'fields-wd1-2026-09-26b-s003-rollback:4c555421-7d9c-4921-b5c1-f5e386c6f6bd:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic stones'' restored on Asklepion, Kos', '[{"source": "https://ancient-greece.org/archaeology/kos-asklepieion/", "url": "https://ancient-greece.org/archaeology/kos-asklepieion/", "quote": "or the Sanctuary of Asklepios, is one of the most significant healing centers of the ancient world.", "outcome": "found"}, {"source": "https://madainproject.com/asclepieion_of_kos", "url": "https://madainproject.com/asclepieion_of_kos", "quote": "was a major sanctuary complex dedicated to Asclepius, the Greek god of medicine", "outcome": "found"}, {"source": "https://kos.gr/historical-monuments-and-museums/asclepieion", "url": "https://kos.gr/historical-monuments-and-museums/asclepieion", "quote": "In ancient times, it was a place of worship of the god Asclepius as well as a place of healing and teaching of medicine.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Asklepieion on Kos is described as the Sanctuary of Asklepios, a sanctuary complex of temples and altar terraces used for worship and healing, not as megalithic stones; the Greek Ministry of Culture also titles its page The sanctuary of Asklepios at Kos. Sanctuary is the canonical type that fits.", "value_page": null}]'::jsonb),
    ('4c555421-7d9c-4921-b5c1-f5e386c6f6bd'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Temple_of_Asclepius,_Kos', 'https://en.wikipedia.org/wiki/Asclepieion', 'fields-wd1-2026-09-26b-s003-rollback:4c555421-7d9c-4921-b5c1-f5e386c6f6bd:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Asclepieion'' restored on Asklepion, Kos', '[{"source": "https://en.wikipedia.org/wiki/Temple_of_Asclepius,_Kos", "url": "https://en.wikipedia.org/wiki/Temple_of_Asclepius,_Kos", "quote": "The Temple of Asclepius or Asclepieion of Kos was one of the most famous temples dedicated to Asclepius in the ancient world.", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/22681.html", "url": "https://imperium.ahlfeldt.se/places/22681.html", "quote": "Information about the ancient place located at Asklepieion, Kos", "outcome": "found"}, {"source": "https://cs.wikipedia.org/wiki/Askl%C3%A9pion_(K%C3%B3s)", "url": "https://cs.wikipedia.org/wiki/Askl%C3%A9pion_(K%C3%B3s)", "quote": "Asklépion (Kós)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0062)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the generic article on Asclepieia; the English Wikipedia article ''Temple of Asclepius, Kos'' is about this very sanctuary (its Czech sister article is titled ''Asklépion (Kós)''), which the Digital Atlas of the Roman Empire also records as the ancient place Asklepieion, Kos.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Temple of Asclepius, Kos", "unreadable": false, "wikibase_item": "Q2655433"}}]'::jsonb),
    ('4c6645cc-de9a-4a21-b932-809f7600337c'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4c6645cc-de9a-4a21-b932-809f7600337c:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Berry Head', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4c6645cc-de9a-4a21-b932-809f7600337c'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s003-rollback:4c6645cc-de9a-4a21-b932-809f7600337c:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1000'' restored on Berry Head', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call the promontory fort ''probably of Early Iron Age date'' (Megalithic Portal, after the Devon HER) or simply Iron Age (Wikipedia); only a local newspaper column gives a hedged range (''likely dated to between 750 BC and 50 AD''), so no two independent sources date its start to a year or century and the field is emptied.", "value_page": null}]'::jsonb),
    ('4c6645cc-de9a-4a21-b932-809f7600337c'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:4c6645cc-de9a-4a21-b932-809f7600337c:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Berry Head', '[{"source": "https://www.megalithic.co.uk/article.php?sid=62517", "url": "https://www.megalithic.co.uk/article.php?sid=62517", "quote": "A promontory fort on Berry Head, probably of Early Iron Age date, was destroyed by the building of the fort in 1803.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Berry_Head", "url": "https://en.wikipedia.org/wiki/Berry_Head", "quote": "Berry Head is the site of an Iron Age hill fort which was mostly destroyed by the construction between 1794 and 1804 of extensive fortifications", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as an Iron Age promontory/hill fort on the headland (the Wikidata item is only the cape); Fort is the most specific canonical type for it, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('4c6645cc-de9a-4a21-b932-809f7600337c'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=62517', 'https://en.wikipedia.org/wiki/Berry_Head', 'fields-wd1-2026-09-26b-s003-rollback:4c6645cc-de9a-4a21-b932-809f7600337c:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Berry_Head'' restored on Berry Head', '[{"source": "https://www.megalithic.co.uk/article.php?sid=62517", "url": "https://www.megalithic.co.uk/article.php?sid=62517", "quote": "Site Name: Berry Head Promontory Fort Country: England County: Devon Type: Promontory Fort / Cliff Castle", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Berry_Head", "url": "https://en.wikipedia.org/wiki/Berry_Head", "quote": "Berry Head is the site of an Iron Age hill fort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the headland (cape) and gives the fort one sentence; the Megalithic Portal entry ''Berry Head Promontory Fort'' is a page about the Iron Age fort itself, and no Wikipedia article or readable register entry exists for it.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4d056246-58ef-4d82-8b67-79a8b3def7a5'::uuid, 'site_type', 'Sanctuary', 'Megalithic stones', 'fields-wd1-2026-09-26b-s003-rollback:4d056246-58ef-4d82-8b67-79a8b3def7a5:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Megalithic stones'' restored on Delphi', '[{"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2507", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2507", "quote": "At the foot of Mount Parnassos, within the angle formed by the twin rocks of the Phaedriades, lies the Pan-Hellenic sanctuary of Delphi, which had the most famous oracle of ancient Greece.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Delphi", "url": "https://en.wikipedia.org/wiki/Delphi", "quote": "was an ancient sacred precinct in central Greece", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture describes Delphi as the Pan-Hellenic sanctuary with the most famous oracle of ancient Greece, and Wikipedia calls it an ancient sacred precinct; the stored point lies in the Sanctuary of Apollo. Delphi was also a polis, but the site is known and mapped as its sanctuary, and it is not megalithic, so Sanctuary is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('4d0fa83d-8685-49ee-ba7d-27d9f256e303'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s003-rollback:4d0fa83d-8685-49ee-ba7d-27d9f256e303:period_name', 'rollback of fields-wd1-2026-09-26b-s003: period_name ''1500 - 500 BC'' restored on Craig Rhiwarth', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4d0fa83d-8685-49ee-ba7d-27d9f256e303'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s003-rollback:4d0fa83d-8685-49ee-ba7d-27d9f256e303:period_start', 'rollback of fields-wd1-2026-09-26b-s003: period_start ''-1500'' restored on Craig Rhiwarth', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "clear", "status": "MISSING", "reasoning": "Only Cadw dates the hillfort with years (probably Iron Age, c. 800 BC - AD 74); Wikipedia and Heneb say only that it may have begun in the late Bronze Age, and Powys Heritage notes that without modern excavation the dating rests on morphology, so no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('4d0fa83d-8685-49ee-ba7d-27d9f256e303'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s003-rollback:4d0fa83d-8685-49ee-ba7d-27d9f256e303:site_type', 'rollback of fields-wd1-2026-09-26b-s003: site_type ''Fortress/citadel'' restored on Craig Rhiwarth', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=729", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=729", "quote": "The monument comprises the remains of a hillfort, which probably dates to the Iron Age period (c. 800 BC - AD 74, the Roman conquest of Wales).", "outcome": "found"}, {"source": "https://powysheritage.org/sites/craig-rhiwarth/", "url": "https://powysheritage.org/sites/craig-rhiwarth/", "quote": "A fort with a legible interior lets you think about it as somewhere people lived rather than as a set of banks, and Craig Rhiwarth is one of the better examples in mid Wales.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (site type Hillfort) and Powys Heritage describe Craig Rhiwarth as a hillfort, not a fortress or citadel; Fort is the canonical type for a hillfort.", "value_page": null}]'::jsonb),
    ('4d70c735-5eb1-4907-a2a3-9c25871a951b'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Stane_Street', 'https://en.wikipedia.org/wiki/Stane_Street_(Chichester)', 'fields-wd1-2026-09-26b-s003-rollback:4d70c735-5eb1-4907-a2a3-9c25871a951b:source_url', 'rollback of fields-wd1-2026-09-26b-s003: source_url ''https://en.wikipedia.org/wiki/Stane_Street_(Chichester)'' restored on Stane Street, Chichester', '[{"source": "https://en.wikipedia.org/wiki/Stane_Street", "url": "https://en.wikipedia.org/wiki/Stane_Street", "quote": "Stane Street shows clearly the engineering principles that the Romans used when building roads.", "outcome": "found"}, {"source": "https://dorkingmuseum.org.uk/stane-street-mystery/", "url": "https://dorkingmuseum.org.uk/stane-street-mystery/", "quote": "Stane Street (which means Stoney Street), linked the Roman seaport at Chichester (on the south coast) to the centre of London.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Stane_Street_(Chichester)'' is a redirect. The article it lands on, ''Stane Street'', is the article about this London-Chichester Roman road (the Colchester road has its own article), so its own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Stane Street", "unreadable": false, "wikibase_item": "Q205511"}}]'::jsonb);
